/* =========================================================
   V118 ON-CHAIN V4 MARKET ACTIVITY EVIDENCE
   ========================================================= */

function onChainV4MarketEvidence(
  watched,
  activity
) {
  const swaps =
    safeNumber(
      activity?.swaps
    );

  const liquidityEvents =
    safeNumber(
      activity?.liquidityEvents
    );

  const poolSpecific =
    activity?.poolSpecific ===
      true;

  const poolId =
    normalize(
      watched?.poolId ||
      watched?.primaryPoolId ||
      watched?.lastPoolId
    ) ||
    null;

  const marketExists =
    poolSpecific &&
    (
      swaps >
        0 ||
      liquidityEvents >
        0
    );

  return {
    verified:
      marketExists,

    status:
      marketExists
        ? "ONCHAIN_V4_MARKET_ACTIVITY_VERIFIED"
        : "ONCHAIN_V4_MARKET_ACTIVITY_UNVERIFIED",

    source:
      "ONCHAIN_V4",

    poolSpecific,

    poolId,

    swaps,

    liquidityEvents,

    /*
     * Important safety distinction:
     * raw V4 activity proves an active market/pool, but does NOT by itself
     * prove a USD price or USD liquidity amount.
     */
    usdPriceVerified:
      false,

    usdLiquidityVerified:
      false
  };
}

/* =========================================================
   V447 HISTORICAL LOG CAPABILITY GUARD + VALUATION TARGETING
   ========================================================= */

const V447_HISTORICAL_LOG_403_COOLDOWN_MS =
  6 * 60 * 60 * 1000;

function historicalLogCapabilityRootV447(
  state
) {
  if (
    !state ||
    typeof state !== "object"
  ) {
    return null;
  }

  state.historicalLogCapabilityV447 =
    state.historicalLogCapabilityV447 &&
    typeof state.historicalLogCapabilityV447 === "object"
      ? state.historicalLogCapabilityV447
      : {
          chainstack403Count: 0,
          chainstackBlockedUntil: null,
          lastAttemptAt: null,
          lastSuccessAt: null,
          lastHttp403At: null,
          lastError: null
        };

  return state.historicalLogCapabilityV447;
}

function historicalLogChainstackBlockedV447(
  state
) {
  const root =
    historicalLogCapabilityRootV447(
      state
    );

  const blockedUntil =
    safeNumber(
      root?.chainstackBlockedUntil
    );

  return (
    blockedUntil > Date.now()
  );
}

function recordHistoricalLogResultV447(
  state,
  {
    success = false,
    http403 = false,
    error = null
  } = {}
) {
  const root =
    historicalLogCapabilityRootV447(
      state
    );

  if (!root) {
    return;
  }

  const at =
    Date.now();

  root.lastAttemptAt =
    at;

  if (success) {
    root.lastSuccessAt =
      at;

    root.lastError =
      null;

    root.chainstack403Count =
      0;

    root.chainstackBlockedUntil =
      null;

    return;
  }

  root.lastError =
    error || null;

  if (http403) {
    root.lastHttp403At =
      at;

    root.chainstack403Count =
      safeNumber(
        root.chainstack403Count
      ) + 1;

    root.chainstackBlockedUntil =
      at +
      V447_HISTORICAL_LOG_403_COOLDOWN_MS;
  }
}

function reservesLensValuationReadinessV447(
  state,
  candidate,
  poolKey
) {
  const priceVerified =
    candidate
      ?.market
      ?.onChainMarketFoundationV438
      ?.verifiedObservedExecutionPrice ===
      true &&
    safeNumber(
      candidate
        ?.market
        ?.onChainMarketFoundationV438
        ?.medianObservedPriceUsd
    ) > 0;

  if (
    poolKey?.verified !==
      true
  ) {
    return {
      valuationReady: false,
      priceVerified,
      quoteUsdReady: false,
      quoteType: null,
      reason:
        "POOLKEY_INCOMPLETE_V447"
    };
  }

  const token =
    normalize(
      candidate?.address
    );

  const quote =
    poolKey.currency0 === token
      ? poolKey.currency1
      : (
          poolKey.currency1 === token
            ? poolKey.currency0
            : null
        );

  let quoteUsdReady =
    false;

  let quoteType =
    null;

  if (
    quote ===
      CANONICAL_USDG_V179
  ) {
    quoteUsdReady =
      true;

    quoteType =
      "CANONICAL_USDG";
  } else if (
    quote === ZERO ||
    quote ===
      CANONICAL_WETH_V179
  ) {
    const reference =
      bestVerifiedWethUsdGReferenceV195(
        state
      );

    quoteUsdReady =
      reference?.verified ===
      true &&
      safeNumber(
        reference?.priceUsdGPerWeth
      ) > 0;

    quoteType =
      quote === ZERO
        ? "NATIVE_ETH"
        : "CANONICAL_WETH";
  }

  return {
    valuationReady:
      priceVerified &&
      quoteUsdReady,
    priceVerified,
    quoteUsdReady,
    quoteType,
    reason:
      priceVerified &&
      quoteUsdReady
        ? "VALUATION_READY_V447"
        : (
            !priceVerified
              ? "V438_PRICE_NOT_READY_V447"
              : "QUOTE_USD_REFERENCE_NOT_READY_V447"
          )
  };
}

/* =========================================================
   V443 HISTORICAL IMMUTABLE POOLKEY RECOVERY
   ========================================================= */

function historicalPoolKeyRecoveryTargetV443(
  state,
  candidates
) {
  const rows =
    Array.isArray(candidates)
      ? candidates
      : [];

  const ranked =
    rows
      .map(
        candidate => {
          const address =
            normalize(
              candidate?.address
            );

          const watched =
            findWatched(
              state,
              address
            );

          const candidatePoolIds =
            new Set();

          for (
            const value
            of [
              candidate
                ?.onChainPoolIdentityV153
                ?.poolId,
              candidate
                ?.market
                ?.onChainMarketFoundationV438
                ?.latestPoolId,
              watched?.poolId,
              watched?.primaryPoolId,
              watched?.lastPoolId
            ]
          ) {
            const id =
              normalize(value);

            if (
              /^0x[a-f0-9]{64}$/.test(
                String(id || "")
              )
            ) {
              candidatePoolIds.add(
                id
              );
            }
          }

          for (
            const pool
            of Array.isArray(
              watched?.pools
            )
              ? watched.pools
              : []
          ) {
            const id =
              normalize(
                pool?.poolId
              );

            if (
              /^0x[a-f0-9]{64}$/.test(
                String(id || "")
              )
            ) {
              candidatePoolIds.add(
                id
              );
            }
          }

          let best =
            null;

          for (
            const poolId
            of candidatePoolIds
          ) {
            const persisted =
              state
                ?.poolRegistry
                ?.[poolId] ||
              null;

            const watchedPool =
              (
                Array.isArray(
                  watched?.pools
                )
                  ? watched.pools
                  : []
              ).find(
                pool =>
                  normalize(
                    pool?.poolId
                  ) ===
                  poolId
              ) ||
              null;

            const merged = {
              ...(
                persisted &&
                typeof persisted ===
                  "object"
                  ? persisted
                  : {}
              ),
              ...(
                watchedPool &&
                typeof watchedPool ===
                  "object"
                  ? watchedPool
                  : {}
              ),
              poolId
            };

            const alreadyComplete =
              completePoolKeyV441(
                state,
                {
                  address,
                  onChainPoolIdentityV153: {
                    poolId
                  }
                }
              )?.verified ===
              true;

            if (alreadyComplete) {
              continue;
            }

            const blockNumber =
              safeNumber(
                merged?.blockNumber
              );

            if (
              blockNumber <= 0
            ) {
              continue;
            }

            const priceVerified =
              candidate
                ?.market
                ?.onChainMarketFoundationV438
                ?.verifiedObservedExecutionPrice ===
                true;

            const marketVerified =
              candidate
                ?.market
                ?.verified ===
                true;

            const score =
              (priceVerified ? 1000 : 0) +
              (marketVerified ? 200 : 0) +
              safeNumber(
                candidate?.analysisPriority
              );

            const row = {
              candidate,
              address,
              watched,
              poolId,
              blockNumber,
              score,
              persistedSource:
                persisted
                  ? "POOL_REGISTRY"
                  : (
                      watchedPool
                        ? "WATCHED_POOL"
                        : null
                    )
            };

            if (
              !best ||
              row.score >
                best.score
            ) {
              best = row;
            }
          }

          return best;
        }
      )
      .filter(Boolean)
      .sort(
        (a, b) =>
          b.score -
          a.score
      );

  return ranked[0] || null;
}

async function blockscoutExactHistoricalInitializeV448(
  state,
  budget,
  poolId,
  blockNumber
) {
  const base = {
    attempted: false,
    requestSent: false,
    provider: "BLOCKSCOUT",
    poolId:
      normalize(poolId),
    blockNumber:
      safeNumber(blockNumber) || null,
    status: null,
    httpStatus: null,
    resolvedPool: null,
    logsReturned: 0,
    externalRequestsUsed: 0,
    cooldownUntil: null,
    error: null
  };

  const normalizedPoolId =
    normalize(poolId);

  const targetBlock =
    safeNumber(blockNumber);

  if (
    !/^0x[a-f0-9]{64}$/.test(
      String(normalizedPoolId || "")
    ) ||
    targetBlock <= 0
  ) {
    return {
      ...base,
      status:
        "INVALID_POOL_OR_BLOCK_V448"
    };
  }

  const service =
    blockscoutWideInitializeServiceV184(
      state
    );

  const now =
    Date.now();

  const cooldownUntil =
    safeNumber(
      service?.cooldownUntil
    );

  if (
    cooldownUntil > now
  ) {
    return {
      ...base,
      status:
        "BLOCKSCOUT_HISTORICAL_INITIALIZE_COOLDOWN_V448",
      cooldownUntil
    };
  }

  if (
    !budgetAvailable(
      budget,
      "analysis"
    ) ||
    !consumeBudget(
      budget,
      "analysis",
      "BLOCKSCOUT_EXACT_HISTORICAL_INITIALIZE_V448"
    )
  ) {
    return {
      ...base,
      status:
        "ANALYSIS_BUDGET_UNAVAILABLE_V448"
    };
  }

  const exactBlock =
    Math.floor(
      targetBlock
    );

  const url =
    `${BLOCKSCOUT}/api?module=logs&action=getLogs` +
    `&fromBlock=${exactBlock}` +
    `&toBlock=${exactBlock}` +
    `&address=${POOL_MANAGER}` +
    `&topic0=${INITIALIZE_TOPIC}` +
    `&topic1=${normalizedPoolId}` +
    `&topic0_1_opr=and`;

  service.totalRequests =
    safeNumber(
      service.totalRequests
    ) + 1;

  service.lastRequestAt =
    Date.now();

  service.lastStatus =
    "REQUESTING_V448";

  try {
    const response =
      await fetch(
        url,
        {
          headers: {
            accept:
              "application/json"
          }
        }
      );

    const httpStatus =
      response.status;

    if (
      httpStatus === 429
    ) {
      const backoffMs =
        registerBlockscoutWideInitialize429V184(
          state
        );

      return {
        ...base,
        attempted: true,
        requestSent: true,
        externalRequestsUsed: 1,
        httpStatus,
        status:
          "BLOCKSCOUT_HTTP_429_V448",
        cooldownUntil:
          Date.now() +
          backoffMs
      };
    }

    if (!response.ok) {
      service.lastStatus =
        `HTTP_${httpStatus}_V448`;

      return {
        ...base,
        attempted: true,
        requestSent: true,
        externalRequestsUsed: 1,
        httpStatus,
        status:
          `BLOCKSCOUT_HTTP_${httpStatus}_V448`
      };
    }

    let payload =
      null;

    try {
      payload =
        await response.json();
    } catch (error) {
      service.lastStatus =
        "JSON_DECODE_FAILED_V448";

      return {
        ...base,
        attempted: true,
        requestSent: true,
        externalRequestsUsed: 1,
        httpStatus,
        status:
          "BLOCKSCOUT_JSON_DECODE_FAILED_V448",
        error:
          errorString(error)
      };
    }

    const rows =
      Array.isArray(
        payload?.result
      )
        ? payload.result
        : [];

    let resolvedPool =
      null;

    for (
      const row
      of rows
    ) {
      const decoded =
        decodeInitialize(
          row
        );

      if (
        decoded &&
        normalize(
          decoded.poolId
        ) ===
          normalizedPoolId &&
        decoded
          ?.poolKeyCompleteV441 ===
          true
      ) {
        resolvedPool =
          decoded;
        break;
      }
    }

    service.lastSuccessAt =
      Date.now();

    service.consecutive429s =
      0;

    service.cooldownUntil =
      null;

    service.lastBackoffMs =
      null;

    service.lastStatus =
      resolvedPool
        ? "RESOLVED_V448"
        : (
            rows.length
              ? "FOUND_LOG_POOLKEY_INCOMPLETE_V448"
              : "EMPTY_V448"
          );

    return {
      ...base,
      attempted: true,
      requestSent: true,
      externalRequestsUsed: 1,
      httpStatus,
      status:
        resolvedPool
          ? "RESOLVED_V448"
          : (
              rows.length
                ? "FOUND_LOG_POOLKEY_INCOMPLETE_V448"
                : "EMPTY_V448"
            ),
      resolvedPool,
      logsReturned:
        rows.length
    };
  } catch (error) {
    service.lastStatus =
      "FETCH_ERROR_V448";

    return {
      ...base,
      attempted: true,
      requestSent: true,
      externalRequestsUsed: 1,
      status:
        "BLOCKSCOUT_FETCH_ERROR_V448",
      error:
        errorString(error)
    };
  }
}

async function recoverHistoricalPoolKeyV443(
  env,
  state,
  budget,
  candidates
) {
  const base = {
    enabled: true,
    attempted: false,
    requestSent: false,
    maxCandidatesPerScan: 1,
    maxRecoveryRequestsPerScan: 1,
    providerPreference:
      "CHAINSTACK_MANAGED_ANALYSIS_ROUTER",
    candidateAddress: null,
    symbol: null,
    poolId: null,
    blockNumber: null,
    persistedSource: null,
    status:
      "NO_ELIGIBLE_INCOMPLETE_HISTORICAL_POOLKEY_V443",
    provider: null,
    logsReturned: 0,
    resolved: false,
    recoveredPoolKey: null,
    externalRequestsUsed: 0,
    poolKeyFieldsGuessed: false,
    requestCeilingChanged: false
  };

  const target =
    historicalPoolKeyRecoveryTargetV443(
      state,
      candidates
    );

  if (!target) {
    return base;
  }

  const {
    candidate,
    address,
    poolId,
    blockNumber,
    persistedSource
  } = target;

  if (
    !budgetAvailable(
      budget,
      "analysis"
    )
  ) {
    return {
      ...base,
      candidateAddress:
        address,
      symbol:
        candidate?.symbol ||
        null,
      poolId,
      blockNumber,
      persistedSource,
      status:
        "ANALYSIS_BUDGET_UNAVAILABLE_V443"
    };
  }

  const recoveryV448 =
    await blockscoutExactHistoricalInitializeV448(
      state,
      budget,
      poolId,
      blockNumber
    );

  const used =
    safeNumber(
      recoveryV448
        ?.externalRequestsUsed
    );

  if (
    recoveryV448
      ?.resolvedPool
      ?.poolKeyCompleteV441 !==
      true
  ) {
    return {
      ...base,
      attempted:
        recoveryV448
          ?.attempted ===
          true,
      requestSent:
        recoveryV448
          ?.requestSent ===
          true,
      candidateAddress:
        address,
      symbol:
        candidate?.symbol ||
        null,
      poolId,
      blockNumber,
      persistedSource,
      status:
        recoveryV448
          ?.status ||
        "BLOCKSCOUT_HISTORICAL_POOLKEY_UNRESOLVED_V448",
      provider:
        "BLOCKSCOUT",
      logsReturned:
        safeNumber(
          recoveryV448
            ?.logsReturned
        ),
      resolved: false,
      recoveredPoolKey: null,
      externalRequestsUsed:
        used,
      poolKeyFieldsGuessed:
        false,
      blockscoutRecoveryV448:
        recoveryV448
    };
  }

  const resolvedPool =
    recoveryV448
      .resolvedPool;

  registerPoolMapping(
    state,
    resolvedPool
  );

  for (
    const tokenAddress
    of [
      resolvedPool.currency0,
      resolvedPool.currency1
    ]
  ) {
    if (
      !isAddress(
        tokenAddress
      ) ||
      tokenAddress === ZERO ||
      knownQuote(
        tokenAddress
      )
    ) {
      continue;
    }

    addWatch(
      state,
      tokenAddress,
      resolvedPool,
      "V443_HISTORICAL_INITIALIZE_POOLKEY_RECOVERY"
    );
  }

  const recoveredKey =
    completePoolKeyV441(
      state,
      {
        address,
        onChainPoolIdentityV153: {
          poolId
        }
      }
    );

  return {
    ...base,
    attempted: true,
    requestSent: true,
    candidateAddress:
      address,
    symbol:
      candidate?.symbol ||
      null,
    poolId,
    blockNumber,
    persistedSource,
    status:
      recoveredKey
        ?.verified === true
        ? "HISTORICAL_POOLKEY_RECOVERED_BLOCKSCOUT_V448"
        : "HISTORICAL_INITIALIZE_DECODED_BUT_REGISTRY_INCOMPLETE_V448",
    provider:
      "BLOCKSCOUT",
    logsReturned:
      safeNumber(
        recoveryV448
          ?.logsReturned
      ),
    resolved:
      recoveredKey
        ?.verified === true,
    recoveredPoolKey:
      recoveredKey
        ?.verified === true
        ? recoveredKey
        : null,
    externalRequestsUsed:
      used,
    blockscoutRecoveryV448:
      recoveryV448
  };
}

/* =========================================================
   V441 CANONICAL UNISWAP V4 RESERVESLENS LIQUIDITY DIAGNOSTIC
   ========================================================= */

/*
 * Canonical Uniswap v4 deployment on Robinhood Chain.
 * ReservesLens is the canonical cross-chain CREATE2 deployment.
 *
 * Diagnostic only in V441:
 * - no market promotion
 * - no liquidity gate change
 * - no scoring/qualification change
 */
const UNISWAP_V4_STATE_VIEW_V441 =
  "0xf3334192d15450cdd385c8b70e03f9a6bd9e673b";

const UNISWAP_V4_RESERVES_LENS_V441 =
  "0x0000001b173c3bbf3984d417d8614e3eed34865b";

/* getPoolTVL(address,(address,address,uint24,int24,address)) */
const RESERVES_LENS_GET_POOL_TVL_SELECTOR_V441 =
  "f95138f2";

function abiEncodeAddressWordV441(
  address
) {
  const a =
    normalize(address);

  if (!isAddress(a)) {
    return null;
  }

  return a
    .replace(/^0x/, "")
    .padStart(64, "0");
}

function abiEncodeUintWordV441(
  value
) {
  try {
    const v =
      BigInt(value);

    if (v < 0n) {
      return null;
    }

    return v
      .toString(16)
      .padStart(64, "0");
  } catch {
    return null;
  }
}

function abiEncodeSignedWordV441(
  value,
  bits = 24
) {
  try {
    let v =
      BigInt(value);

    const width =
      BigInt(bits);

    const min =
      -(1n << (width - 1n));

    const max =
      (1n << (width - 1n)) - 1n;

    if (
      v < min ||
      v > max
    ) {
      return null;
    }

    if (v < 0n) {
      v =
        (1n << 256n) + v;
    }

    return v
      .toString(16)
      .padStart(64, "0");
  } catch {
    return null;
  }
}

function abiDecodeWordV441(
  data,
  index
) {
  const clean =
    String(data || "")
      .replace(/^0x/, "");

  const start =
    index * 64;

  if (
    clean.length <
      start + 64
  ) {
    return null;
  }

  const word =
    clean.slice(
      start,
      start + 64
    );

  return /^[0-9a-fA-F]{64}$/.test(word)
    ? word
    : null;
}

function abiDecodeUintWordV441(
  data,
  index
) {
  const word =
    abiDecodeWordV441(
      data,
      index
    );

  if (!word) {
    return null;
  }

  try {
    return BigInt(
      "0x" + word
    );
  } catch {
    return null;
  }
}

function abiDecodeSigned24WordV441(
  data,
  index
) {
  const raw =
    abiDecodeUintWordV441(
      data,
      index
    );

  if (raw === null) {
    return null;
  }

  const low =
    raw & 0xffffffn;

  return Number(
    low >= 0x800000n
      ? low - 0x1000000n
      : low
  );
}

function abiDecodeAddressWordV441(
  data,
  index
) {
  const word =
    abiDecodeWordV441(
      data,
      index
    );

  if (!word) {
    return null;
  }

  const address =
    normalize(
      "0x" +
      word.slice(24)
    );

  return isAddress(address)
    ? address
    : null;
}

function completePoolKeyV441(
  state,
  candidate
) {
  const address =
    normalize(
      candidate?.address
    );

  const watched =
    findWatched(
      state,
      address
    );

  const poolId =
    normalize(
      candidate
        ?.onChainPoolIdentityV153
        ?.poolId
    );

  const rows =
    [];

  for (
    const pool
    of Array.isArray(watched?.pools)
      ? watched.pools
      : []
  ) {
    rows.push(pool);
  }

  if (
    poolId &&
    state?.poolRegistry?.[poolId]
  ) {
    rows.push(
      state.poolRegistry[poolId]
    );
  }

  for (
    const pool
    of rows
  ) {
    if (
      poolId &&
      normalize(pool?.poolId) !==
        poolId
    ) {
      continue;
    }

    const currency0 =
      normalize(
        pool?.currency0
      );

    const currency1 =
      normalize(
        pool?.currency1
      );

    const hooks =
      normalize(
        pool?.hooks
      );

    const fee =
      safeNumber(
        pool?.fee
      );

    const tickSpacing =
      Number(
        pool?.tickSpacing
      );

    if (
      !isAddress(currency0) ||
      !isAddress(currency1) ||
      !isAddress(hooks) ||
      !Number.isInteger(fee) ||
      fee < 0 ||
      fee > 0xffffff ||
      !Number.isInteger(
        tickSpacing
      ) ||
      tickSpacing <= 0
    ) {
      continue;
    }

    return {
      verified: true,
      source:
        pool?.poolKeySourceV441 ||
        "PERSISTED_INITIALIZE_POOL_KEY_V441",
      poolId:
        normalize(pool?.poolId) ||
        poolId ||
        null,
      currency0,
      currency1,
      fee,
      tickSpacing,
      hooks
    };
  }

  return {
    verified: false,
    source: null,
    poolId:
      poolId || null,
    currency0: null,
    currency1: null,
    fee: null,
    tickSpacing: null,
    hooks: null
  };
}

function encodeReservesLensCallV441(
  poolKey
) {
  if (
    poolKey?.verified !==
      true
  ) {
    return null;
  }

  const words = [
    abiEncodeAddressWordV441(
      POOL_MANAGER
    ),
    abiEncodeAddressWordV441(
      poolKey.currency0
    ),
    abiEncodeAddressWordV441(
      poolKey.currency1
    ),
    abiEncodeUintWordV441(
      poolKey.fee
    ),
    abiEncodeSignedWordV441(
      poolKey.tickSpacing,
      24
    ),
    abiEncodeAddressWordV441(
      poolKey.hooks
    )
  ];

  if (
    words.some(
      word => !word
    )
  ) {
    return null;
  }

  return (
    "0x" +
    RESERVES_LENS_GET_POOL_TVL_SELECTOR_V441 +
    words.join("")
  );
}

function decimalFromRawUnsignedV441(
  raw,
  decimals
) {
  if (
    typeof raw !== "bigint" ||
    raw < 0n ||
    !Number.isInteger(decimals) ||
    decimals < 0 ||
    decimals > 36
  ) {
    return null;
  }

  return bigintDecimalToNumberV187(
    raw,
    decimals
  );
}

function persistVerifiedWethUsdGReferenceV452(
  state,
  {
    sameBatch = null,
    uniswapV196 = null,
    v3V195 = null
  } = {}
) {
  if (!state || typeof state !== "object") {
    return {
      persisted: false,
      status: "STATE_UNAVAILABLE_V452",
      source: null,
      priceUsdGPerWeth: null,
      externalRequestsAdded: 0
    };
  }

  const candidates = [
    {
      row: sameBatch,
      source:
        sameBatch?.source ||
        "SAME_BATCH_CANONICAL_WETH_USDG_V452",
      trust:
        "VERIFIED_SAME_BATCH_CANONICAL_SWAP"
    },
    {
      row: uniswapV196,
      source:
        uniswapV196?.source ||
        "UNISWAP_AGGREGATED_NATIVE_ETH_TO_CANONICAL_USDG_QUOTE_V196",
      trust:
        "VERIFIED_NATIVE_ETH_TO_CANONICAL_USDG_QUOTE"
    },
    {
      row: v3V195,
      source:
        v3V195?.source ||
        "UNISWAP_V3_CANONICAL_WETH_USDG_SLOT0_V195",
      trust:
        "VERIFIED_CANONICAL_V3_WETH_USDG"
    }
  ];

  for (const candidate of candidates) {
    const row = candidate.row;
    const price =
      safeNumber(
        row?.priceUsdGPerWeth
      );

    if (
      row?.verified !== true ||
      !Number.isFinite(price) ||
      price <= 0
    ) {
      continue;
    }

    const verifiedAt = Date.now();

    state.verifiedWethUsdGReferenceV452 = {
      verified: true,
      priceUsdGPerWeth: price,
      verifiedAt,
      source: candidate.source,
      trust: candidate.trust,
      poolAddress:
        normalize(row?.poolAddress) || null,
      poolId:
        /^0x[a-f0-9]{64}$/.test(
          normalize(row?.poolId)
        )
          ? normalize(row.poolId)
          : null,
      fee:
        row?.fee ?? null,
      routing:
        row?.routing ?? null,
      originalStatus:
        row?.status || null,
      bridgeVersion: "V452"
    };

    return {
      persisted: true,
      status:
        "VERIFIED_WETH_USDG_REFERENCE_BRIDGED_V452",
      source: candidate.source,
      trust: candidate.trust,
      priceUsdGPerWeth: price,
      verifiedAt,
      externalRequestsAdded: 0
    };
  }

  return {
    persisted: false,
    status:
      "NO_VERIFIED_REFERENCE_AVAILABLE_TO_BRIDGE_V452",
    source: null,
    trust: null,
    priceUsdGPerWeth: null,
    verifiedAt: null,
    externalRequestsAdded: 0
  };
}

function bestVerifiedWethUsdGReferenceV195(
  state
) {
  const maxAgeMs =
    30 * 60 * 1000;

  const bridgedV452 =
    state
      ?.verifiedWethUsdGReferenceV452;

  const bridgedPrice =
    safeNumber(
      bridgedV452
        ?.priceUsdGPerWeth
    );

  const bridgedVerifiedAt =
    safeNumber(
      bridgedV452
        ?.verifiedAt
    );

  const bridgedAgeMs =
    bridgedVerifiedAt > 0
      ? Math.max(
          0,
          Date.now() -
          bridgedVerifiedAt
        )
      : null;

  if (
    bridgedV452?.verified === true &&
    Number.isFinite(bridgedPrice) &&
    bridgedPrice > 0 &&
    bridgedVerifiedAt > 0 &&
    bridgedAgeMs !== null &&
    bridgedAgeMs <= maxAgeMs
  ) {
    return {
      verified: true,
      source:
        bridgedV452?.source ||
        "VERIFIED_WETH_USDG_REFERENCE_BRIDGE_V452",
      trust:
        bridgedV452?.trust || null,
      priceUsdGPerWeth:
        bridgedPrice,
      verifiedAt:
        bridgedVerifiedAt,
      ageMs:
        bridgedAgeMs,
      poolAddress:
        normalize(
          bridgedV452?.poolAddress
        ) || null,
      poolId:
        bridgedV452?.poolId || null,
      fee:
        bridgedV452?.fee ?? null,
      routing:
        bridgedV452?.routing ?? null,
      bridgeVersion: "V452",
      externalRequestsUsed: 0
    };
  }

  const cachedV3 =
    state
      ?.v3WethUsdGReferenceV195;

  const price =
    safeNumber(
      cachedV3
        ?.priceUsdGPerWeth
    );

  const verifiedAt =
    safeNumber(
      cachedV3
        ?.verifiedAt
    );

  const ageMs =
    verifiedAt > 0
      ? Math.max(
          0,
          Date.now() -
          verifiedAt
        )
      : null;

  if (
    Number.isFinite(price) &&
    price > 0 &&
    verifiedAt > 0 &&
    ageMs !== null &&
    ageMs <= maxAgeMs
  ) {
    return {
      verified: true,
      source:
        cachedV3?.verifiedByV291 === true
          ? "CACHED_VERIFIED_DIRECT_ONCHAIN_WETH_USDG_V291_V446"
          : "CACHED_VERIFIED_V3_WETH_USDG_REFERENCE_V195_V446",
      priceUsdGPerWeth: price,
      verifiedAt,
      ageMs,
      poolAddress:
        normalize(cachedV3?.poolAddress) || null,
      fee:
        cachedV3?.fee ?? null,
      externalRequestsUsed: 0
    };
  }

  return null;
}

function reservesLensUsdValuationV441(
  candidate,
  poolKey,
  decoded,
  state
) {
  const token =
    normalize(
      candidate?.address
    );

  const tokenDecimals =
    Number(
      candidate?.decimals
    );

  const tokenIs0 =
    poolKey.currency0 ===
      token;

  const tokenIs1 =
    poolKey.currency1 ===
      token;

  if (
    !tokenIs0 &&
    !tokenIs1
  ) {
    return {
      verified: false,
      status:
        "CANDIDATE_NOT_IN_POOL_KEY_V441"
    };
  }

  const quote =
    tokenIs0
      ? poolKey.currency1
      : poolKey.currency0;

  const candidateRaw =
    tokenIs0
      ? decoded.coreAmount0
      : decoded.coreAmount1;

  const quoteRaw =
    tokenIs0
      ? decoded.coreAmount1
      : decoded.coreAmount0;

  const quoteDecimals =
    quote === ZERO ||
    quote === CANONICAL_WETH_V179
      ? 18
      : (
          quote ===
            CANONICAL_USDG_V179
            ? CANONICAL_USDG_DECIMALS_V179
            : null
        );

  const candidateAmount =
    decimalFromRawUnsignedV441(
      candidateRaw,
      tokenDecimals
    );

  const quoteAmount =
    Number.isInteger(
      quoteDecimals
    )
      ? decimalFromRawUnsignedV441(
          quoteRaw,
          quoteDecimals
        )
      : null;

  let quoteUsd =
    null;

  let usdBasis =
    null;

  if (
    quote ===
      CANONICAL_USDG_V179 &&
    Number.isFinite(
      quoteAmount
    )
  ) {
    quoteUsd =
      quoteAmount;

    usdBasis =
      "CANONICAL_USDG_1_TO_1_USD_V441";
  } else if (
    (
      quote === ZERO ||
      quote ===
        CANONICAL_WETH_V179
    ) &&
    Number.isFinite(
      quoteAmount
    )
  ) {
    const reference =
      bestVerifiedWethUsdGReferenceV195(
        state
      );

    const wethUsd =
      safeNumber(
        reference
          ?.priceUsdGPerWeth
      );

    if (wethUsd > 0) {
      quoteUsd =
        quoteAmount *
        wethUsd;

      usdBasis =
        reference?.source ||
        "VERIFIED_WETH_USDG_REFERENCE_V441";
    }
  }

  const observedPrice =
    safeNumber(
      candidate
        ?.market
        ?.onChainMarketFoundationV438
        ?.medianObservedPriceUsd
    );

  const candidateUsd =
    observedPrice > 0 &&
    Number.isFinite(
      candidateAmount
    )
      ? candidateAmount *
        observedPrice
      : null;

  const totalCoreLiquidityUsd =
    Number.isFinite(
      quoteUsd
    ) &&
    Number.isFinite(
      candidateUsd
    )
      ? quoteUsd +
        candidateUsd
      : null;

  const customAccounting =
    decoded
      ?.hasCustomAccounting ===
      true;

  return {
    verified:
      Number.isFinite(
        totalCoreLiquidityUsd
      ) &&
      totalCoreLiquidityUsd >= 0 &&
      !customAccounting,
    status:
      customAccounting
        ? "CUSTOM_ACCOUNTING_CORE_RESERVES_APPROXIMATE_V441"
        : (
            Number.isFinite(
              totalCoreLiquidityUsd
            )
              ? "CORE_POOL_USD_LIQUIDITY_DIAGNOSTIC_VERIFIED_V441"
              : "USD_VALUATION_INCOMPLETE_V441"
          ),
    candidateAddress:
      token,
    quoteTokenAddress:
      quote,
    candidateAmount,
    quoteAmount,
    candidateUsd,
    quoteUsd,
    totalCoreLiquidityUsd,
    candidateUsdPriceBasis:
      observedPrice > 0
        ? "V438_MEDIAN_EXACT_USD_EXECUTION_PRICE"
        : null,
    quoteUsdBasis:
      usdBasis,
    hasCustomAccounting:
      customAccounting,
    qualificationPromotionAllowed:
      false
  };
}

function decodeReservesLensResultV441(
  data
) {
  const words =
    String(data || "")
      .replace(/^0x/, "");

  if (
    !/^[0-9a-fA-F]+$/.test(
      words
    ) ||
    words.length <
      14 * 64
  ) {
    return null;
  }

  const coreAmount0 =
    abiDecodeUintWordV441(
      data,
      0
    );

  const coreAmount1 =
    abiDecodeUintWordV441(
      data,
      1
    );

  const hookReserves0 =
    abiDecodeUintWordV441(
      data,
      2
    );

  const hookReserves1 =
    abiDecodeUintWordV441(
      data,
      3
    );

  const hookEffective0 =
    abiDecodeUintWordV441(
      data,
      4
    );

  const hookEffective1 =
    abiDecodeUintWordV441(
      data,
      5
    );

  const sqrtPriceX96 =
    abiDecodeUintWordV441(
      data,
      6
    );

  const tick =
    abiDecodeSigned24WordV441(
      data,
      7
    );

  const activeLiquidity =
    abiDecodeUintWordV441(
      data,
      8
    );

  const blockNumber =
    abiDecodeUintWordV441(
      data,
      9
    );

  const statsProvider =
    abiDecodeAddressWordV441(
      data,
      10
    );

  const hookPermissions =
    abiDecodeUintWordV441(
      data,
      11
    );

  const customAccounting =
    abiDecodeUintWordV441(
      data,
      12
    );

  const statsStatus =
    abiDecodeUintWordV441(
      data,
      13
    );

  if (
    coreAmount0 === null ||
    coreAmount1 === null ||
    sqrtPriceX96 === null ||
    activeLiquidity === null
  ) {
    return null;
  }

  return {
    coreAmount0,
    coreAmount1,
    hookReserves0,
    hookReserves1,
    hookEffective0,
    hookEffective1,
    sqrtPriceX96,
    tick,
    activeLiquidity,
    blockNumber,
    statsProvider,
    hookPermissions:
      hookPermissions !== null
        ? Number(
            hookPermissions
          )
        : null,
    hasCustomAccounting:
      customAccounting === 1n,
    statsStatus:
      statsStatus !== null
        ? Number(statsStatus)
        : null
  };
}

async function reservesLensLiquidityDiagnosticV441(
  env,
  state,
  budget,
  candidates
) {
  const base = {
    enabled: true,
    diagnosticOnly: true,
    source:
      "CANONICAL_UNISWAP_V4_RESERVES_LENS",
    reservesLens:
      UNISWAP_V4_RESERVES_LENS_V441,
    stateView:
      UNISWAP_V4_STATE_VIEW_V441,
    poolManager:
      POOL_MANAGER,
    attempted: false,
    requestSent: false,
    candidateAddress: null,
    symbol: null,
    poolId: null,
    completePoolKey: false,
    status:
      "NO_ELIGIBLE_CANDIDATE_V441",
    decoded: null,
    usdValuation: null,
    externalRequestsUsed: 0,
    marketVerifiedChanged: false,
    liquidityGateChanged: false,
    scoringChanged: false,
    qualificationChanged: false,
    telegramThresholdChanged: false
  };

  const ranked =
    (Array.isArray(candidates)
      ? candidates
      : [])
      .map(
        candidate => {
          const key =
            completePoolKeyV441(
              state,
              candidate
            );

          const readiness =
            reservesLensValuationReadinessV447(
              state,
              candidate,
              key
            );

          const marketVerified =
            candidate
              ?.market
              ?.verified ===
              true;

          return {
            candidate,
            key,
            readiness,
            score:
              (
                readiness
                  ?.valuationReady ===
                  true
                  ? 5000
                  : 0
              ) +
              (
                readiness
                  ?.priceVerified ===
                  true
                  ? 1000
                  : 0
              ) +
              (
                readiness
                  ?.quoteUsdReady ===
                  true
                  ? 500
                  : 0
              ) +
              (marketVerified ? 200 : 0) +
              safeNumber(
                candidate?.analysisPriority
              )
          };
        }
      )
      .sort(
        (a, b) =>
          b.score - a.score
      );

  let target =
    null;

  let poolKey =
    null;

  let selectedReadinessV447 =
    null;

  for (
    const row
    of ranked
  ) {
    const key =
      row?.key;

    if (
      key?.verified === true
    ) {
      target =
        row.candidate;

      poolKey =
        key;

      selectedReadinessV447 =
        row?.readiness ||
        null;

      break;
    }
  }

  if (
    !target ||
    !poolKey
  ) {
    return {
      ...base,
      status:
        "NO_RETURNED_CANDIDATE_WITH_COMPLETE_POOL_KEY_V441"
    };
  }

  const calldata =
    encodeReservesLensCallV441(
      poolKey
    );

  if (!calldata) {
    return {
      ...base,
      candidateAddress:
        normalize(
          target?.address
        ),
      symbol:
        target?.symbol ||
        null,
      poolId:
        poolKey?.poolId ||
        null,
      completePoolKey: true,
      status:
        "RESERVES_LENS_CALLDATA_ENCODING_FAILED_V441"
    };
  }

  if (
    !budgetAvailable(
      budget,
      "analysis"
    )
  ) {
    return {
      ...base,
      candidateAddress:
        normalize(
          target?.address
        ),
      symbol:
        target?.symbol ||
        null,
      poolId:
        poolKey?.poolId ||
        null,
      completePoolKey: true,
      status:
        "ANALYSIS_BUDGET_UNAVAILABLE_V441"
    };
  }

  const before =
    safeNumber(
      budget?.totalUsed
    );

  const call =
    await rpc(
      env,
      "eth_call",
      [
        {
          to:
            UNISWAP_V4_RESERVES_LENS_V441,
          data:
            calldata
        },
        "latest"
      ],
      budget,
      "analysis"
    );

  const used =
    Math.max(
      0,
      safeNumber(
        budget?.totalUsed
      ) - before
    );

  if (
    call?.result === null ||
    call?.result === undefined
  ) {
    return {
      ...base,
      attempted: true,
      requestSent:
        used > 0,
      candidateAddress:
        normalize(
          target?.address
        ),
      symbol:
        target?.symbol ||
        null,
      poolId:
        poolKey?.poolId ||
        null,
      completePoolKey: true,
      poolKey,
      status:
        "RESERVES_LENS_RPC_FAILED_V442",
      provider:
        call?.provider ||
        null,
      error:
        call?.error ||
        null,
      externalRequestsUsed:
        used,
      managedRpcRoutingV442: {
        enabled: true,
        preferredProvider:
          "CHAINSTACK",
        phase:
          "analysis",
        legacyManualRpcV292Used:
          false
      }
    };
  }

  const decoded =
    decodeReservesLensResultV441(
      call.result
    );

  if (!decoded) {
    return {
      ...base,
      attempted: true,
      requestSent: true,
      candidateAddress:
        normalize(
          target?.address
        ),
      symbol:
        target?.symbol ||
        null,
      poolId:
        poolKey?.poolId ||
        null,
      completePoolKey: true,
      poolKey,
      status:
        "RESERVES_LENS_RESPONSE_DECODE_FAILED_V441",
      provider:
        call?.provider ||
        null,
      externalRequestsUsed:
        used,
      managedRpcRoutingV442: {
        enabled: true,
        preferredProvider:
          "CHAINSTACK",
        actualProvider:
          call?.provider ||
          null,
        phase:
          "analysis",
        legacyManualRpcV292Used:
          false
      }
    };
  }

  const valuation =
    reservesLensUsdValuationV441(
      target,
      poolKey,
      decoded,
      state
    );

  const serializableDecoded = {
    coreAmount0:
      decoded.coreAmount0
        ?.toString() ||
      null,
    coreAmount1:
      decoded.coreAmount1
        ?.toString() ||
      null,
    hookReserves0:
      decoded.hookReserves0
        ?.toString() ||
      null,
    hookReserves1:
      decoded.hookReserves1
        ?.toString() ||
      null,
    hookEffective0:
      decoded.hookEffective0
        ?.toString() ||
      null,
    hookEffective1:
      decoded.hookEffective1
        ?.toString() ||
      null,
    sqrtPriceX96:
      decoded.sqrtPriceX96
        ?.toString() ||
      null,
    tick:
      decoded.tick,
    activeLiquidity:
      decoded.activeLiquidity
        ?.toString() ||
      null,
    blockNumber:
      decoded.blockNumber
        ?.toString() ||
      null,
    statsProvider:
      decoded.statsProvider,
    hookPermissions:
      decoded.hookPermissions,
    hasCustomAccounting:
      decoded.hasCustomAccounting,
    statsStatus:
      decoded.statsStatus
  };

  target.reservesLensLiquidityDiagnosticV441 = {
    verified:
      valuation?.verified ===
      true,
    status:
      valuation?.status ||
      "DECODED_V441",
    poolId:
      poolKey.poolId,
    poolKey,
    decoded:
      serializableDecoded,
    usdValuation:
      valuation,
    diagnosticOnly:
      true,
    promotionApplied:
      false,
    valuationTargetingV447:
      selectedReadinessV447
  };

  return {
    ...base,
    attempted: true,
    requestSent: true,
    candidateAddress:
      normalize(
        target?.address
      ),
    symbol:
      target?.symbol ||
      null,
    poolId:
      poolKey.poolId,
    completePoolKey: true,
    poolKey,
    status:
      valuation?.status ||
      "RESERVES_LENS_DECODED_V441",
    provider:
      call?.provider ||
      null,
    decoded:
      serializableDecoded,
    usdValuation:
      valuation,
    externalRequestsUsed:
      used,
    valuationTargetingV447:
      selectedReadinessV447,
    managedRpcRoutingV442: {
      enabled: true,
      preferredProvider:
        "CHAINSTACK",
      actualProvider:
        call?.provider ||
        null,
      phase:
        "analysis",
      legacyManualRpcV292Used:
        false
    }
  };
}

/* =========================================================
   V449 LIQUIDITY CROSS-CHECK + TELEGRAM SEND-STATUS DIAGNOSTICS
   ========================================================= */

const PONS_V2_MEME_HOOK_V453 =
  "0xe5e702641ea86f4ae6cc3cdaed2b886f976be044";

function classifyHookLiquiditySemanticsV453(
  reservesLens
) {
  const hasEvidence =
    Boolean(
      reservesLens &&
      typeof reservesLens === "object" &&
      (
        reservesLens?.attempted === true ||
        reservesLens?.requestSent === true ||
        reservesLens?.poolId ||
        reservesLens?.poolKey
      )
    );

  if (!hasEvidence) {
    return {
      enabled: true,
      strictEvidenceGuardV454: true,
      evidencePresent: false,
      poolKeyVerified: false,
      identified: false,
      protocol: null,
      hook: null,
      classification:
        "NO_RESERVESLENS_LIQUIDITY_EVIDENCE_V454",
      coreLiquiditySemanticallyUsable:
        false,
      hookManagedTradingPrincipalIncluded:
        null,
      hookAccruedFeesExcluded:
        null,
      rationale:
        "NO_RESERVESLENS_RESULT_OR_POOL_IDENTITY_EVIDENCE",
      genericHasCustomAccounting:
        null,
      promotionAllowed:
        false,
      diagnosticOnly:
        true
    };
  }

  const poolKeyVerified =
    reservesLens
      ?.poolKey
      ?.verified ===
      true;

  const poolId =
    normalize(
      reservesLens
        ?.poolId ||
      reservesLens
        ?.poolKey
        ?.poolId
    );

  const currency0 =
    normalize(
      reservesLens
        ?.poolKey
        ?.currency0
    );

  const currency1 =
    normalize(
      reservesLens
        ?.poolKey
        ?.currency1
    );

  const hook =
    normalize(
      reservesLens
        ?.poolKey
        ?.hooks
    );

  const completePoolKey =
    Boolean(
      poolKeyVerified &&
      /^0x[a-f0-9]{64}$/.test(
        String(
          poolId || ""
        )
      ) &&
      /^0x[a-f0-9]{40}$/.test(
        String(
          currency0 || ""
        )
      ) &&
      /^0x[a-f0-9]{40}$/.test(
        String(
          currency1 || ""
        )
      ) &&
      /^0x[a-f0-9]{40}$/.test(
        String(
          hook || ""
        )
      ) &&
      Number.isFinite(
        safeNumber(
          reservesLens
            ?.poolKey
            ?.fee
        )
      ) &&
      Number.isFinite(
        safeNumber(
          reservesLens
            ?.poolKey
            ?.tickSpacing
        )
      )
    );

  if (!completePoolKey) {
    return {
      enabled: true,
      strictEvidenceGuardV454: true,
      evidencePresent: true,
      poolKeyVerified:
        poolKeyVerified,
      completePoolKey: false,
      poolId:
        poolId || null,
      identified: false,
      protocol: null,
      hook:
        hook || null,
      classification:
        "RESERVESLENS_POOLKEY_UNVERIFIED_V454",
      coreLiquiditySemanticallyUsable:
        false,
      hookManagedTradingPrincipalIncluded:
        null,
      hookAccruedFeesExcluded:
        null,
      rationale:
        "VERIFIED_COMPLETE_POOLKEY_REQUIRED_BEFORE_LIQUIDITY_SEMANTICS",
      genericHasCustomAccounting:
        reservesLens
          ?.decoded
          ?.hasCustomAccounting ??
        null,
      promotionAllowed:
        false,
      diagnosticOnly:
        true
    };
  }

  const hasCustomAccounting =
    reservesLens
      ?.decoded
      ?.hasCustomAccounting ===
      true;

  if (
    hook ===
    PONS_V2_MEME_HOOK_V453
  ) {
    return {
      enabled: true,
      strictEvidenceGuardV454: true,
      evidencePresent: true,
      poolKeyVerified: true,
      completePoolKey: true,
      poolId,
      identified: true,
      protocol:
        "PONS_V2",
      hook,
      classification:
        "FEE_ACCOUNTING_ONLY_CORE_AMM_LIQUIDITY_V453",
      coreLiquiditySemanticallyUsable:
        true,
      hookManagedTradingPrincipalIncluded:
        false,
      hookAccruedFeesExcluded:
        true,
      rationale:
        "PONS_V2_SINGLE_LOCKED_FULL_RANGE_CORE_POSITION_AND_POST_SWAP_FEE_ACCOUNTING",
      genericHasCustomAccounting:
        hasCustomAccounting,
      promotionAllowed:
        false,
      diagnosticOnly:
        true
    };
  }

  if (hasCustomAccounting) {
    return {
      enabled: true,
      strictEvidenceGuardV454: true,
      evidencePresent: true,
      poolKeyVerified: true,
      completePoolKey: true,
      poolId,
      identified: false,
      protocol: null,
      hook,
      classification:
        "UNKNOWN_CUSTOM_ACCOUNTING_REMAINS_BLOCKED_V453",
      coreLiquiditySemanticallyUsable:
        false,
      hookManagedTradingPrincipalIncluded:
        null,
      hookAccruedFeesExcluded:
        true,
      rationale:
        "CUSTOM_ACCOUNTING_SEMANTICS_NOT_INDEPENDENTLY_VERIFIED",
      genericHasCustomAccounting:
        true,
      promotionAllowed:
        false,
      diagnosticOnly:
        true
    };
  }

  return {
    enabled: true,
    strictEvidenceGuardV454: true,
    evidencePresent: true,
    poolKeyVerified: true,
    completePoolKey: true,
    poolId,
    identified:
      hook ===
      "0x0000000000000000000000000000000000000000",
    protocol:
      hook ===
      "0x0000000000000000000000000000000000000000"
        ? "NO_HOOK"
        : null,
    hook,
    classification:
      "CORE_AMM_LIQUIDITY_NO_CUSTOM_ACCOUNTING_V453",
    coreLiquiditySemanticallyUsable:
      true,
    hookManagedTradingPrincipalIncluded:
      false,
    hookAccruedFeesExcluded:
      true,
    rationale:
      "VERIFIED_COMPLETE_POOLKEY_AND_NO_CUSTOM_ACCOUNTING_FLAG",
    genericHasCustomAccounting:
      false,
    promotionAllowed:
      false,
    diagnosticOnly:
      true
  };
}

function exactPoolPriceEvidenceV455(
  candidate,
  poolId
) {
  const foundation =
    candidate
      ?.market
      ?.onChainMarketFoundationV438;

  const exactPoolId =
    normalize(poolId);

  const nowMs =
    Date.now();

  const maxAgeMs =
    safeNumber(
      foundation?.maxSampleAgeMs
    ) > 0
      ? safeNumber(
          foundation.maxSampleAgeMs
        )
      : ONCHAIN_MARKET_PRICE_MAX_AGE_MS_V438;

  const samples =
    (
      Array.isArray(
        foundation?.samples
      )
        ? foundation.samples
        : []
    )
      .filter(row => {
        const rowPoolId =
          normalize(
            row?.poolId
          );

        const observedAt =
          safeNumber(
            row?.observedAt
          );

        const priceUsd =
          safeNumber(
            row?.executionPriceUsd
          );

        return (
          /^0x[a-f0-9]{64}$/.test(
            String(
              exactPoolId || ""
            )
          ) &&
          rowPoolId ===
            exactPoolId &&
          observedAt > 0 &&
          nowMs - observedAt >=
            0 &&
          nowMs - observedAt <=
            maxAgeMs &&
          priceUsd > 0
        );
      })
      .sort(
        (a, b) =>
          safeNumber(
            b?.observedAt
          ) -
          safeNumber(
            a?.observedAt
          )
      );

  const prices =
    samples.map(
      row =>
        safeNumber(
          row?.executionPriceUsd
        )
    );

  const medianPriceUsd =
    medianNumberV187(
      prices
    );

  const latest =
    samples[0] || null;

  const verified =
    foundation
      ?.verifiedObservedExecutionPrice ===
      true &&
    samples.length > 0 &&
    Number.isFinite(
      medianPriceUsd
    ) &&
    medianPriceUsd > 0 &&
    safeNumber(
      latest?.observedAt
    ) > 0;

  return {
    verified,
    source:
      "V438_EXACT_USD_EXECUTIONS_EXACT_POOL_ONLY_V455",
    poolId:
      exactPoolId || null,
    sampleCount:
      samples.length,
    medianPriceUsd:
      verified
        ? medianPriceUsd
        : null,
    latestPriceUsd:
      verified
        ? safeNumber(
            latest
              ?.executionPriceUsd
          )
        : null,
    latestObservedAt:
      verified
        ? safeNumber(
            latest?.observedAt
          )
        : null,
    latestAgeMs:
      verified
        ? Math.max(
            0,
            nowMs -
            safeNumber(
              latest?.observedAt
            )
          )
        : null,
    maxAgeMs,
    mixedPoolMedianUsed:
      false,
    samples:
      samples.slice(
        0,
        ONCHAIN_MARKET_PRICE_MAX_SAMPLES_V438
      )
  };
}

function strictOnChainMarketFallbackEligibilityV455(
  candidate
) {
  const market =
    candidate?.market || {};

  const lens =
    candidate
      ?.reservesLensLiquidityDiagnosticV441;

  const semantics =
    candidate
      ?.hookLiquiditySemanticsV453;

  const poolId =
    normalize(
      lens?.poolId ||
      lens?.poolKey?.poolId
    );

  const price =
    exactPoolPriceEvidenceV455(
      candidate,
      poolId
    );

  const liquidityUsd =
    safeNumber(
      lens
        ?.usdValuation
        ?.totalCoreLiquidityUsd
    );

  const poolKeyVerified =
    lens
      ?.poolKey
      ?.verified ===
      true &&
    lens?.completePoolKey !==
      false;

  const lensVerified =
    lens?.verified ===
      true &&
    lens
      ?.usdValuation
      ?.verified ===
      true &&
    liquidityUsd > 0;

  const semanticUsable =
    semantics
      ?.strictEvidenceGuardV454 ===
      true &&
    semantics
      ?.evidencePresent ===
      true &&
    semantics
      ?.poolKeyVerified ===
      true &&
    semantics
      ?.completePoolKey ===
      true &&
    semantics
      ?.coreLiquiditySemanticallyUsable ===
      true;

  const semanticPoolId =
    normalize(
      semantics?.poolId
    );

  const exactPoolIdentity =
    /^0x[a-f0-9]{64}$/.test(
      String(
        poolId || ""
      )
    ) &&
    (
      !semanticPoolId ||
      semanticPoolId ===
        poolId
    ) &&
    price?.poolId ===
      poolId;

  const reasons = [];

  if (
    market?.verified === true
  ) {
    reasons.push(
      "PROVIDER_OR_EXISTING_MARKET_ALREADY_VERIFIED"
    );
  }

  if (!poolKeyVerified) {
    reasons.push(
      "VERIFIED_COMPLETE_POOLKEY_REQUIRED_V455"
    );
  }

  if (!lensVerified) {
    reasons.push(
      "VERIFIED_RESERVESLENS_USD_LIQUIDITY_REQUIRED_V455"
    );
  }

  if (!semanticUsable) {
    reasons.push(
      "LIQUIDITY_SEMANTICS_NOT_USABLE_V455"
    );
  }

  if (!price?.verified) {
    reasons.push(
      "RECENT_EXACT_POOL_USD_PRICE_REQUIRED_V455"
    );
  }

  if (!exactPoolIdentity) {
    reasons.push(
      "EXACT_POOL_IDENTITY_MISMATCH_V455"
    );
  }

  return {
    enabled: true,
    eligible:
      reasons.length ===
      0,
    reasons,
    poolId:
      poolId || null,
    exactPoolIdentity,
    poolKeyVerified,
    lensVerified,
    semanticUsable,
    priceEvidence:
      price,
    liquidityUsd:
      lensVerified
        ? liquidityUsd
        : null,
    addsExternalRequests:
      0
  };
}

function promoteStrictOnChainMarketFallbackV455(
  candidate
) {
  const eligibility =
    strictOnChainMarketFallbackEligibilityV455(
      candidate
    );

  const originalMarket =
    candidate?.market || {};

  if (!eligibility.eligible) {
    candidate.onChainMarketFallbackV455 = {
      ...eligibility,
      promoted: false,
      marketVerifiedChanged:
        false,
      qualificationThresholdsChanged:
        false
    };

    return {
      promoted: false,
      eligibility:
        candidate
          .onChainMarketFallbackV455
    };
  }

  const priceUsd =
    safeNumber(
      eligibility
        ?.priceEvidence
        ?.medianPriceUsd
    );

  const liquidityUsd =
    safeNumber(
      eligibility
        ?.liquidityUsd
    );

  const decimals =
    Number(
      candidate
        ?.validation
        ?.decimals
    );

  let totalSupply =
    null;

  try {
    totalSupply =
      candidate
        ?.validation
        ?.totalSupply !==
          null &&
      candidate
        ?.validation
        ?.totalSupply !==
          undefined &&
      Number.isInteger(
        decimals
      ) &&
      decimals >= 0 &&
      decimals <= 36
        ? decimalRawToNumberV438(
            candidate
              .validation
              .totalSupply,
            decimals
          )
        : null;
  } catch {
    totalSupply = null;
  }

  const fdv =
    Number.isFinite(
      totalSupply
    ) &&
    totalSupply > 0 &&
    priceUsd > 0
      ? totalSupply *
        priceUsd
      : null;

  const foundation =
    originalMarket
      ?.onChainMarketFoundationV438 ||
    null;

  candidate.market = {
    ...originalMarket,
    verified: true,
    cached: false,
    cacheAgeMs: 0,
    status:
      "VERIFIED_ONCHAIN_EXACT_POOL_FALLBACK_V455",
    source:
      "ONCHAIN_EXACT_POOL_FALLBACK_V455",
    priceUsd:
      String(
        priceUsd
      ),
    liquidityUsd,
    marketCap: null,
    fdv:
      Number.isFinite(fdv) &&
      fdv > 0
        ? fdv
        : null,
    volume: {
      m5: null,
      h1: null,
      h24: null
    },
    buyPressure1h: null,
    pairCreatedAt: null,
    exactPoolIdV455:
      eligibility.poolId,
    onChainMarketFoundationV438:
      foundation
        ? {
            ...foundation,
            usdLiquidityVerified:
              true,
            fullMarketPromotionEligible:
              true,
            remainingRequirement:
              null,
            marketVerifiedChanged:
              true,
            liquidityGateChanged:
              true,
            promotionSourceV455:
              "ONCHAIN_EXACT_POOL_FALLBACK_V455",
            exactPoolPriceEvidenceV455:
              eligibility
                .priceEvidence,
            exactPoolLiquidityUsdV455:
              liquidityUsd
          }
        : foundation,
    onChainMarketFallbackV455: {
      ...eligibility,
      promoted: true,
      source:
        "ONCHAIN_EXACT_POOL_FALLBACK_V455",
      priceUsd,
      liquidityUsd,
      fdv:
        Number.isFinite(fdv) &&
        fdv > 0
          ? fdv
          : null,
      marketCap:
        null,
      circulatingSupplyAssumed:
        false,
      providerVolumePromoted:
        false,
      providerBuyPressurePromoted:
        false,
      pairCreatedAtPromoted:
        false,
      marketVerifiedChanged:
        true,
      qualificationThresholdsChanged:
        false,
      addsExternalRequests:
        0
    }
  };

  candidate.onChainMarketFallbackV455 =
    candidate
      .market
      .onChainMarketFallbackV455;

  return {
    promoted: true,
    eligibility:
      candidate
        .onChainMarketFallbackV455
  };
}


function refreshScannerFunnelFinalCountsV456(
  scannerFunnel,
  candidates,
  telegramResults
) {
  if (
    !scannerFunnel ||
    typeof scannerFunnel !== "object"
  ) {
    return null;
  }

  const returned =
    Array.isArray(candidates)
      ? candidates.filter(
          candidate =>
            candidate &&
            candidate.returnedCandidate !==
              false
        )
      : [];

  const marketVerified =
    returned.filter(
      candidate =>
        candidate
          ?.market
          ?.verified === true
    ).length;

  const holderEvidenceVerified =
    returned.filter(candidate => {
      const holders =
        candidate?.holders || {};

      return (
        holders
          ?.fullyVerified ===
          true ||
        (
          holders
            ?.integrityVerified ===
            true &&
          holders
            ?.concentrationVerified ===
            true
        )
      );
    }).length;

  const telegramQualified =
    returned.filter(
      candidate =>
        candidate
          ?.telegram
          ?.qualifies === true
    ).length;

  const telegramSent =
    Array.isArray(
      telegramResults
    )
      ? telegramResults.filter(
          result =>
            result?.sent === true
        ).length
      : safeNumber(
          scannerFunnel
            ?.telegramSent
        );

  scannerFunnel.marketVerified =
    marketVerified;

  scannerFunnel.holderEvidenceVerified =
    holderEvidenceVerified;

  scannerFunnel.telegramQualified =
    telegramQualified;

  scannerFunnel.telegramSent =
    telegramSent;

  scannerFunnel.finalStateTelemetryV456 = {
    applied: true,
    source:
      "POST_V455_FINAL_CANDIDATE_STATE",
    returnedCandidates:
      returned.length,
    marketVerified,
    holderEvidenceVerified,
    telegramQualified,
    telegramSent,
    fallbackPromotedCount:
      returned.filter(
        candidate =>
          candidate
            ?.market
            ?.onChainMarketFallbackV455
            ?.promoted === true
      ).length,
    countsReflectPostFallbackState:
      true,
    scoringChanged:
      false,
    qualificationChanged:
      false,
    thresholdsChanged:
      false,
    externalRequestsAdded:
      0
  };

  return scannerFunnel
    .finalStateTelemetryV456;
}

function refreshCandidateAfterMarketPromotionV455(
  candidate,
  state
) {
  if (
    !candidate ||
    candidate
      ?.market
      ?.onChainMarketFallbackV455
      ?.promoted !==
      true
  ) {
    return {
      refreshed: false,
      reason:
        "NO_V455_MARKET_PROMOTION"
    };
  }

  const historical =
    getHistoricalSnapshot(
      state,
      candidate.address
    );

  candidate.momentum =
    momentumAnalysis(
      historical,
      candidate.market,
      candidate.holders,
      candidate
        .liveMomentumActivityV152,
      candidate
        .ponsCurveFlowV216
    );

  candidate.marketQuality =
    marketQuality(
      candidate.market
    );

  /*
   * Do not infer launch age from on-chain market fallback.
   * Verified protocol launch-age evidence remains separate.
   */
  candidate.launchStage =
    launchStage(
      candidate.market
    );

  candidate.risk =
    scoreRisk(
      candidate.validation,
      candidate.market,
      candidate.holders,
      candidate.activity,
      candidate.whaleFlow
    );

  candidate.opportunity =
    scoreOpportunity(
      candidate.validation,
      candidate.market,
      candidate.holders,
      candidate.activity,
      candidate.momentum,
      candidate.marketQuality,
      candidate.whaleFlow,
      candidate.launchStage
    );

  candidate.signalConfirmation =
    signalConfirmation(
      candidate
    );

  candidate.confidence =
    candidateConfidence(
      candidate
    );

  evidenceQualityProtectionV158(
    candidate
  );

  opportunityConfirmationCalibrationV253(
    candidate,
    {
      refreshRaw: true,
      phase:
        "ONCHAIN_MARKET_FALLBACK_V455"
    }
  );

  candidate.holderBreadthV136 =
    healthyHolderBreadthV136(
      candidate.holders
    );

  candidate.analysisPriority =
    analysisPriority(
      candidate
    );

  candidate.marketFallbackRescoreV455 = {
    applied: true,
    source:
      "ONCHAIN_EXACT_POOL_FALLBACK_V455",
    opportunityScore:
      safeNumber(
        candidate
          ?.opportunity
          ?.score
      ),
    confidenceScore:
      safeNumber(
        candidate
          ?.confidence
          ?.score
      ),
    riskScore:
      candidate
        ?.risk
        ?.verified ===
        true
        ? safeNumber(
            candidate
              ?.risk
              ?.score
          )
        : null,
    marketQualityScore:
      candidate
        ?.marketQuality
        ?.verified ===
        true
        ? safeNumber(
            candidate
              ?.marketQuality
              ?.score
          )
        : null,
    thresholdsChanged:
      false
  };

  return {
    refreshed: true,
    ...candidate
      .marketFallbackRescoreV455
  };
}

function providerPoolIdentityV451(candidate) {
  const market =
    candidate?.market || {};

  const values = [
    market?.pairAddress,
    market?.pairId,
    market?.poolId,
    market?.dexPair?.pairAddress,
    market?.dexPair?.pairId,
    market?.dexPair?.poolId,
    candidate?.pairAddress,
    candidate?.pairId
  ];

  for (const value of values) {
    const normalized =
      normalize(value);

    if (
      /^0x[a-f0-9]{64}$/.test(
        String(normalized || "")
      )
    ) {
      return normalized;
    }
  }

  return null;
}

function liquidityCrosscheckV449(candidate) {
  const lens =
    candidate
      ?.reservesLensLiquidityDiagnosticV441;

  const onChainUsd =
    safeNumber(
      lens
        ?.usdValuation
        ?.totalCoreLiquidityUsd
    );

  const providerLiquidityUsd =
    safeNumber(
      candidate
        ?.market
        ?.liquidityUsd
    );

  const onChainVerified =
    lens
      ?.usdValuation
      ?.verified === true &&
    onChainUsd > 0;

  const providerVerified =
    candidate
      ?.market
      ?.verified === true &&
    providerLiquidityUsd > 0;

  const onChainPoolId =
    normalize(
      lens?.poolId ||
      lens?.poolKey?.poolId
    );

  const providerPoolId =
    providerPoolIdentityV451(
      candidate
    );

  const exactPoolIdentityMatched =
    Boolean(
      onChainPoolId &&
      providerPoolId &&
      onChainPoolId === providerPoolId
    );

  if (!onChainVerified || !providerVerified) {
    return {
      enabled: true,
      identityAwareV451: true,
      comparable: false,
      status:
        !onChainVerified
          ? "ONCHAIN_LIQUIDITY_NOT_VERIFIED_V449"
          : "PROVIDER_LIQUIDITY_NOT_VERIFIED_V449",
      onChainPoolId:
        onChainPoolId || null,
      providerPoolId:
        providerPoolId || null,
      exactPoolIdentityMatched,
      onChainCoreLiquidityUsd:
        onChainVerified ? onChainUsd : null,
      providerLiquidityUsd:
        providerVerified ? providerLiquidityUsd : null,
      ratioOnChainToProvider: null,
      absoluteDifferenceUsd: null,
      percentageDifferenceVsProvider: null,
      agreementClass: "NOT_COMPARABLE",
      promotionAllowed: false
    };
  }

  if (!exactPoolIdentityMatched) {
    return {
      enabled: true,
      identityAwareV451: true,
      comparable: false,
      status:
        providerPoolId
          ? "DIFFERENT_POOL_NOT_COMPARABLE_V451"
          : "PROVIDER_POOL_IDENTITY_UNVERIFIED_V451",
      onChainPoolId:
        onChainPoolId || null,
      providerPoolId:
        providerPoolId || null,
      exactPoolIdentityMatched: false,
      onChainCoreLiquidityUsd:
        onChainUsd,
      providerLiquidityUsd,
      ratioOnChainToProvider: null,
      absoluteDifferenceUsd: null,
      percentageDifferenceVsProvider: null,
      agreementClass: "NOT_COMPARABLE",
      promotionAllowed: false,
      interpretation:
        "SAME_TOKEN_DOES_NOT_IMPLY_SAME_POOL_V451"
    };
  }

  const ratio =
    onChainUsd /
    providerLiquidityUsd;

  const absoluteDifferenceUsd =
    Math.abs(
      onChainUsd -
      providerLiquidityUsd
    );

  const percentageDifferenceVsProvider =
    (
      absoluteDifferenceUsd /
      providerLiquidityUsd
    ) * 100;

  let agreementClass =
    "LARGE_DIVERGENCE";

  if (
    ratio >= 0.8 &&
    ratio <= 1.25
  ) {
    agreementClass =
      "CLOSE_AGREEMENT";
  } else if (
    ratio >= 0.5 &&
    ratio <= 2
  ) {
    agreementClass =
      "MODERATE_DIVERGENCE";
  }

  return {
    enabled: true,
    identityAwareV451: true,
    comparable: true,
    status:
      "EXACT_POOL_CROSSCHECK_COMPLETE_V451",
    onChainPoolId,
    providerPoolId,
    exactPoolIdentityMatched: true,
    onChainCoreLiquidityUsd:
      onChainUsd,
    providerLiquidityUsd,
    ratioOnChainToProvider:
      ratio,
    absoluteDifferenceUsd,
    percentageDifferenceVsProvider,
    agreementClass,
    promotionAllowed: false,
    interpretation:
      "EXACT_POOL_ONLY_DIAGNOSTIC_V451"
  };
}

function telegramSendStatusSummaryV449(telegramResults) {
  const rows =
    Array.isArray(telegramResults)
      ? telegramResults
      : [];

  let sent = 0;
  let suppressedByAlertCooldown = 0;
  let otherNotSent = 0;

  for (const row of rows) {
    if (row?.sent === true) {
      sent++;
    } else if (row?.reason === "ALERT_COOLDOWN") {
      suppressedByAlertCooldown++;
    } else {
      otherNotSent++;
    }
  }

  return {
    enabled: true,
    evaluatedQualifiedSendAttempts: rows.length,
    sendEligible:
      Math.max(
        0,
        rows.length -
        suppressedByAlertCooldown
      ),
    sent,
    suppressedByAlertCooldown,
    otherNotSent,
    alertCooldownBehaviourChanged: false,
    duplicateAlertProtectionChanged: false,
    telegramThresholdChanged: false
  };
}

/* =========================================================
   V438 INDEPENDENT ON-CHAIN MARKET VERIFICATION FOUNDATION
   ========================================================= */

const ONCHAIN_MARKET_PRICE_MAX_AGE_MS_V438 =
  30 * 60 * 1000;

const ONCHAIN_MARKET_PRICE_MAX_SAMPLES_V438 =
  7;

function decimalRawToNumberV438(
  raw,
  decimals
) {
  try {
    const value =
      BigInt(
        String(raw)
      );

    const d =
      Number(decimals);

    if (
      value <= 0n ||
      !Number.isInteger(d) ||
      d < 0 ||
      d > 36
    ) {
      return null;
    }

    return bigintDecimalToNumberV187(
      value,
      d
    );
  } catch {
    return null;
  }
}

function verifiedCandidatePoolIdsV438(
  watched
) {
  const ids =
    new Set();

  for (
    const value
    of [
      watched?.poolId,
      watched?.primaryPoolId,
      watched?.lastPoolId
    ]
  ) {
    const id =
      normalize(value);

    if (
      /^0x[a-f0-9]{64}$/.test(
        String(id || "")
      )
    ) {
      ids.add(id);
    }
  }

  for (
    const pool
    of Array.isArray(watched?.pools)
      ? watched.pools
      : []
  ) {
    const id =
      normalize(
        pool?.poolId ||
        pool?.id
      );

    if (
      /^0x[a-f0-9]{64}$/.test(
        String(id || "")
      )
    ) {
      ids.add(id);
    }
  }

  return ids;
}

function onChainMarketFoundationV438(
  state,
  watched,
  validation,
  address
) {
  const token =
    normalize(address);

  const decimals =
    Number(
      validation?.decimals
    );

  const totalSupplyRaw =
    validation?.totalSupply ??
    null;

  const base = {
    enabled: true,
    verifiedObservedExecutionPrice:
      false,
    source:
      "ONCHAIN_V4_EXACT_USD_EXECUTIONS_V438",
    candidateAddress:
      token || null,
    poolIdentityRequired:
      true,
    exactUsdRequired:
      true,
    maxSampleAgeMs:
      ONCHAIN_MARKET_PRICE_MAX_AGE_MS_V438,
    sampleCount: 0,
    medianObservedPriceUsd:
      null,
    latestObservedPriceUsd:
      null,
    latestObservedAt:
      null,
    fullyDilutedValuationUsd:
      null,
    totalSupplyVerified:
      false,
    decimalsVerified:
      false,
    largestObservedExactUsdTrade:
      null,
    executionCapacityInterpretation:
      "OBSERVED_EXECUTED_TRADE_SIZE_NOT_POOL_LIQUIDITY",
    usdLiquidityVerified:
      false,
    fullMarketPromotionEligible:
      false,
    remainingRequirement:
      "INDEPENDENT_EXACT_POOL_USD_LIQUIDITY_PROOF",
    externalRequestsAdded:
      0,
    marketVerifiedChanged:
      false,
    liquidityGateChanged:
      false,
    telegramThresholdChanged:
      false
  };

  if (
    !isAddress(token) ||
    token === ZERO
  ) {
    return {
      ...base,
      status:
        "TOKEN_IDENTITY_UNVERIFIED"
    };
  }

  if (
    !Number.isInteger(decimals) ||
    decimals < 0 ||
    decimals > 36
  ) {
    return {
      ...base,
      status:
        "TOKEN_DECIMALS_UNVERIFIED"
    };
  }

  let totalSupply =
    null;

  try {
    totalSupply =
      totalSupplyRaw !== null &&
      totalSupplyRaw !== undefined
        ? decimalRawToNumberV438(
            totalSupplyRaw,
            decimals
          )
        : null;
  } catch {
    totalSupply = null;
  }

  const ledger =
    state
      ?.onChainDirectionalV179
      ?.[token];

  const records =
    Array.isArray(
      ledger?.records
    )
      ? ledger.records
      : [];

  const allowedPoolIds =
    verifiedCandidatePoolIdsV438(
      watched
    );

  const nowMs =
    Date.now();

  const samples =
    [];

  for (
    const row
    of records
  ) {
    const poolId =
      normalize(
        row?.poolId
      );

    if (
      allowedPoolIds.size > 0 &&
      !allowedPoolIds.has(poolId)
    ) {
      continue;
    }

    if (
      row?.exactUsdVerified !==
        true ||
      !Number.isFinite(
        Number(
          row?.exactUsdAmount
        )
      ) ||
      Number(
        row.exactUsdAmount
      ) <= 0
    ) {
      continue;
    }

    const observedAt =
      safeNumber(
        row?.observedAt
      );

    if (
      observedAt <= 0 ||
      nowMs - observedAt >
        ONCHAIN_MARKET_PRICE_MAX_AGE_MS_V438
    ) {
      continue;
    }

    const candidateAmount =
      decimalRawToNumberV438(
        row?.candidateAmountRaw,
        decimals
      );

    if (
      !Number.isFinite(
        candidateAmount
      ) ||
      candidateAmount <= 0
    ) {
      continue;
    }

    const exactUsd =
      Number(
        row.exactUsdAmount
      );

    const executionPriceUsd =
      exactUsd /
      candidateAmount;

    if (
      !Number.isFinite(
        executionPriceUsd
      ) ||
      executionPriceUsd <= 0
    ) {
      continue;
    }

    samples.push({
      poolId,
      observedAt,
      blockNumber:
        safeNumber(
          row?.blockNumber
        ) || null,
      transactionHash:
        normalize(
          row?.transactionHash
        ) || null,
      side:
        row?.side || null,
      exactUsdAmount:
        exactUsd,
      exactUsdSource:
        row?.exactUsdSource ||
        null,
      candidateAmount,
      executionPriceUsd
    });
  }

  samples.sort(
    (a, b) =>
      safeNumber(
        b.observedAt
      ) -
      safeNumber(
        a.observedAt
      )
  );

  const bounded =
    samples.slice(
      0,
      ONCHAIN_MARKET_PRICE_MAX_SAMPLES_V438
    );

  const prices =
    bounded.map(
      row =>
        row.executionPriceUsd
    );

  const medianPrice =
    medianNumberV187(
      prices
    );

  const latest =
    bounded[0] ||
    null;

  const largestObservedTrade =
    bounded.reduce(
      (max, row) =>
        safeNumber(
          row?.exactUsdAmount
        ) >
        safeNumber(
          max?.exactUsdAmount
        )
          ? row
          : max,
      null
    );

  const priceVerified =
    bounded.length > 0 &&
    Number.isFinite(
      medianPrice
    ) &&
    medianPrice > 0;

  const fdv =
    priceVerified &&
    Number.isFinite(
      totalSupply
    ) &&
    totalSupply > 0
      ? medianPrice *
        totalSupply
      : null;

  return {
    ...base,
    status:
      priceVerified
        ? "VERIFIED_OBSERVED_EXECUTION_PRICE_V438"
        : "NO_RECENT_EXACT_USD_EXECUTION_PRICE_V438",
    verifiedObservedExecutionPrice:
      priceVerified,
    sampleCount:
      bounded.length,
    medianObservedPriceUsd:
      priceVerified
        ? medianPrice
        : null,
    latestObservedPriceUsd:
      latest
        ?.executionPriceUsd ??
      null,
    latestObservedAt:
      latest?.observedAt ||
      null,
    latestPoolId:
      latest?.poolId ||
      null,
    latestExactUsdSource:
      latest?.exactUsdSource ||
      null,
    totalSupplyVerified:
      Number.isFinite(
        totalSupply
      ) &&
      totalSupply > 0,
    decimalsVerified:
      true,
    fullyDilutedValuationUsd:
      Number.isFinite(fdv) &&
      fdv > 0
        ? fdv
        : null,
    largestObservedExactUsdTrade:
      largestObservedTrade
        ? {
            usd:
              largestObservedTrade
                .exactUsdAmount,
            observedAt:
              largestObservedTrade
                .observedAt,
            poolId:
              largestObservedTrade
                .poolId,
            transactionHash:
              largestObservedTrade
                .transactionHash
          }
        : null,
    samples:
      bounded.map(
        row => ({
          poolId:
            row.poolId,
          observedAt:
            row.observedAt,
          blockNumber:
            row.blockNumber,
          transactionHash:
            row.transactionHash,
          side:
            row.side,
          exactUsdAmount:
            row.exactUsdAmount,
          exactUsdSource:
            row.exactUsdSource,
          candidateAmount:
            row.candidateAmount,
          executionPriceUsd:
            row.executionPriceUsd
        })
      ),
    usdLiquidityVerified:
      false,
    fullMarketPromotionEligible:
      false,
    remainingRequirement:
      priceVerified
        ? "INDEPENDENT_EXACT_POOL_USD_LIQUIDITY_PROOF"
        : "RECENT_EXACT_USD_EXECUTION_PRICE_AND_LIQUIDITY_PROOF"
  };
}

