function effectiveAnalysisLimitV416(budget) {
  const configuredLimit = Math.max(
    0,
    safeNumber(budget?.analysis?.limit)
  );

  const baseLimit = Math.max(
    0,
    safeNumber(budget?.analysis?.baseLimitV416) || configuredLimit
  );

  const borrowed =
    budget?.analysis?.adaptiveHeadroomV416?.activated === true
      ? Math.max(0, safeNumber(budget.analysis.adaptiveHeadroomV416.borrowedRequests))
      : 0;

  /* Manual /analyse can intentionally replace analysis.limit; never shrink it. */
  return Math.max(configuredLimit, baseLimit + borrowed);
}

function configureAdaptiveAnalysisHeadroomV416(budget, analysisQueueLength = 0) {
  const telemetry = budget?.analysis?.adaptiveHeadroomV416;
  if (!telemetry?.enabled) return telemetry || null;

  const unusedDiscovery = Math.max(
    0,
    safeNumber(budget?.discovery?.limit) - safeNumber(budget?.discovery?.used)
  );

  const notificationReserveRemaining =
    budget?.notification?.globalReserveActiveV174 === true
      ? Math.max(
          0,
          safeNumber(budget?.notification?.limit) - safeNumber(budget?.notification?.used)
        )
      : 0;

  const preTelegramGlobalRemaining = Math.max(
    0,
    safeNumber(budget?.totalLimit) -
      safeNumber(budget?.totalUsed) -
      notificationReserveRemaining
  );

  const borrowed =
    safeNumber(analysisQueueLength) > 0
      ? Math.max(
          0,
          Math.min(
            V416_MAX_ADAPTIVE_ANALYSIS_BORROW,
            unusedDiscovery,
            preTelegramGlobalRemaining
          )
        )
      : 0;

  telemetry.borrowedRequests = borrowed;
  telemetry.unusedDiscoveryAtActivation = unusedDiscovery;
  telemetry.preTelegramGlobalRemainingAtActivation = preTelegramGlobalRemaining;
  telemetry.activated = borrowed > 0;
  telemetry.activatedAt = borrowed > 0 ? Date.now() : null;
  telemetry.reason =
    borrowed > 0
      ? "UNUSED_DISCOVERY_CAPACITY_LENT_AFTER_DISCOVERY_PASS"
      : safeNumber(analysisQueueLength) <= 0
        ? "NO_ANALYSIS_QUEUE"
        : unusedDiscovery <= 0
          ? "NO_UNUSED_DISCOVERY_CAPACITY"
          : preTelegramGlobalRemaining <= 0
            ? "NO_PRE_TELEGRAM_GLOBAL_HEADROOM"
            : "NO_ADAPTIVE_HEADROOM_AVAILABLE";

  return telemetry;
}

function budgetAvailable(
  budget,
  phase,
  amount = 1
) {
  /*
   * V174:
   * Before Telegram processing finishes, keep the still-unused notification
   * allowance inside the 42-request hard ceiling. This fixes the V173 case
   * where analysis could consume all 42 global requests while the separate
   * notification phase still reported 2 requests "remaining".
   */
  const notificationReserveRemainingV174 =
    (
      budget.notification
        ?.globalReserveActiveV174 ===
        true &&
      phase !==
        "notification"
    )
      ? Math.max(
          0,
          safeNumber(
            budget.notification
              ?.limit
          ) -
          safeNumber(
            budget.notification
              ?.used
          )
        )
      : 0;

  const effectiveGlobalLimitV174 =
    Math.max(
      0,
      budget.totalLimit -
        notificationReserveRemainingV174
    );

  if (
    budget.totalUsed +
      amount >
    effectiveGlobalLimitV174
  ) {
    return false;
  }

  if (
    phase ===
    "system"
  ) {
    return (
      budget.system.used +
        amount <=
      budget.system.limit
    );
  }

  if (
    phase ===
    "analysis"
  ) {
    return (
      budget.analysis.used +
        amount <=
      effectiveAnalysisLimitV416(budget)
    );
  }

  if (
    phase ===
    "notification"
  ) {
    return (
      budget.notification.used +
        amount <=
      budget.notification.limit
    );
  }

  if (
    phase ===
    "discovery-live"
  ) {
    const leavesDownstreamReserve =
      budget.totalUsed +
        amount <=
      budget.totalLimit -
        LIVE_GLOBAL_RESERVE;

    return (
      leavesDownstreamReserve &&
      budget.discovery.used +
          amount <=
        budget.discovery.limit &&
      budget.discovery.liveUsed +
          amount <=
        budget.discovery.liveLimit
    );
  }

  if (
    phase ===
    "discovery-backlog"
  ) {
    const postAnalysisReclaimV170 =
      budget.discovery
        .postAnalysisBacklogReclaimV170 ===
      true;

    const leavesProtectedReserve =
      postAnalysisReclaimV170
        ? budget.totalUsed +
            amount <=
          budget.totalLimit
        : budget.totalUsed +
            amount <=
          budget.totalLimit -
            BACKLOG_GLOBAL_RESERVE;

    return (
      leavesProtectedReserve &&
      budget.discovery.used +
          amount <=
        budget.discovery.limit &&
      budget.discovery.backlogUsed +
          amount <=
        budget.discovery.backlogLimit
    );
  }

  return false;
}

function v182ReserveBlocksAnalysisRequestV226(
  budget,
  amount = 1
) {
  const reserve = budget?.analysis?.blockscoutUsdGReserveV182;
  if (reserve?.active !== true || safeNumber(reserve?.reservedRequests) <= 0) return false;
  const reserved = Math.max(0, safeNumber(reserve.reservedRequests));
  const notificationReserveRemaining =
    budget?.notification?.globalReserveActiveV174 === true
      ? Math.max(0, safeNumber(budget?.notification?.limit) - safeNumber(budget?.notification?.used))
      : 0;
  const preTelegramGlobalLimit = Math.max(0, safeNumber(budget?.totalLimit) - notificationReserveRemaining);
  const analysisBlocked = safeNumber(budget?.analysis?.used) + amount > Math.max(0, effectiveAnalysisLimitV416(budget) - reserved);
  const globalBlocked = safeNumber(budget?.totalUsed) + amount > Math.max(0, preTelegramGlobalLimit - reserved);
  return analysisBlocked || globalBlocked;
}

function yieldV182ReserveToPriorityHolderEvidenceV226(budget, token, reason) {
  const reserve = budget?.analysis?.blockscoutUsdGReserveV182;
  const wasBlocking = v182ReserveBlocksAnalysisRequestV226(budget, 1);
  if (reserve?.active !== true || !wasBlocking) return false;
  reserve.active = false;
  reserve.releasedWithoutUse = true;
  reserve.releasedAt = Date.now();
  reserve.releaseReasonV226 = reason || "PRIORITY_HOLDER_EVIDENCE_COMPLETION";
  reserve.yieldedToPriorityHolderEvidenceV226 = true;
  reserve.yieldedForAddressV226 = normalize(token) || null;
  reserve.wasBlockingAtYieldV226 = true;
  const t = budget.analysis.priorityHolderEvidenceCompletionV226 || (budget.analysis.priorityHolderEvidenceCompletionV226 = {enabled:true,yields:0,address:null,reason:null,yieldedAt:null,reserveWasBlocking:false});
  t.yields = safeNumber(t.yields) + 1;
  t.address = normalize(token) || null;
  t.reason = reserve.releaseReasonV226;
  t.yieldedAt = reserve.releasedAt;
  t.reserveWasBlocking = true;
  return true;
}

function configureAthFairSlotReserveV301(state, budget) {
  const reserve = budget?.analysis?.athFairSlotReserveV301;
  if (!reserve) return null;

  const registry = state?.callPerformanceV270 && typeof state.callPerformanceV270 === "object"
    ? state.callPerformanceV270
    : {};
  const trackedCalls = Object.values(registry)
    .filter(record => Boolean(normalize(record?.address))).length;
  reserve.trackedCalls = trackedCalls;

  if (!trackedCalls) { reserve.active = false; reserve.reason = "NO_TRACKED_CALLS"; return reserve; }

  const service = dexService(state);
  const nowMs = Date.now();
  const cooldownUntil = safeNumber(service?.cooldownUntil);
  if (cooldownUntil && nowMs < cooldownUntil) {
    reserve.active = false; reserve.reason = "DEXSCREENER_COOLDOWN"; return reserve;
  }

  const lastRequestAt = safeNumber(service?.lastRequestAt);
  if (lastRequestAt && nowMs - lastRequestAt < DEXSCREENER_MIN_FRESH_INTERVAL_MS) {
    reserve.active = false; reserve.reason = "FRESH_GUARD"; return reserve;
  }

  const lastFairAttemptAt = safeNumber(service?.lastAthFairSlotAttemptAtV299);
  if (lastFairAttemptAt && nowMs - lastFairAttemptAt < ATH_FAIR_SLOT_MIN_INTERVAL_MS_V299) {
    reserve.active = false; reserve.reason = "FAIR_SLOT_INTERVAL"; return reserve;
  }

  reserve.active = true;
  reserve.activatedAt = nowMs;
  reserve.reason = "ATH_FAIR_SLOT_DUE";
  return reserve;
}

function athFairSlotReserveBlocksAnalysisV301(budget, type, amount = 1) {
  const reserve = budget?.analysis?.athFairSlotReserveV301;
  if (reserve?.active !== true || safeNumber(reserve?.reservedRequests) <= 0) return false;

  if (type === "DEXSCREENER" || type === "DEXSCREENER_ATH_FAIR_SLOT_V299") return false;

  const reserved = Math.max(0, safeNumber(reserve.reservedRequests));
  const notificationReserveRemaining = budget?.notification?.globalReserveActiveV174 === true
    ? Math.max(0, safeNumber(budget?.notification?.limit) - safeNumber(budget?.notification?.used))
    : 0;
  const preTelegramGlobalLimit = Math.max(0, safeNumber(budget?.totalLimit) - notificationReserveRemaining);
  const analysisBlocked = safeNumber(budget?.analysis?.used) + amount > Math.max(0, effectiveAnalysisLimitV416(budget) - reserved);
  const globalBlocked = safeNumber(budget?.totalUsed) + amount > Math.max(0, preTelegramGlobalLimit - reserved);
  return analysisBlocked || globalBlocked;
}

function consumeBudget(
  budget,
  phase,
  type,
  amount = 1
) {
  /*
   * V182:
   * Keep one analysis request and one slot inside the current pre-Telegram
   * global allowance available for the exact Blockscout V4 USDG history call.
   * This does NOT raise any request ceiling. It only changes ordering/priority.
   */
  const usdGReserveV182 =
    budget.analysis
      ?.blockscoutUsdGReserveV182;

  const protectedUsdGTypeV182 =
    "BLOCKSCOUT_V4_USDG_DIRECTIONAL_V180";

  const protectedUsdCompletionTypeV254 =
    "BLOCKSCOUT_V4_USD_COMPLETION_V254";

  const protectedHolderCountCompletionTypeV256 =
    "BLOCKSCOUT_PRO_HOLDER_COUNT_COMPLETION_V256";

  const protectedV458TimestampTypeV459 =
    "BLOCKSCOUT_V458_TIMESTAMP_TO_BLOCK";

  const protectedV458LogsTypeV459 =
    "BLOCKSCOUT_V458_COMPLETE_EXACT_POOL_24H_LOGS";

  /*
   * V459: once a genuinely qualified exact-pool candidate exists, protect two
   * existing analysis slots from LOWER-PRIORITY work. The two V458 requests
   * themselves bypass this guard. No ceiling is raised.
   */
  const completeExactPoolReserveV459 =
    budget.analysis
      ?.completeExactPoolReserveV459;

  if (
    phase === "analysis" &&
    completeExactPoolReserveV459?.active === true &&
    type !== protectedV458TimestampTypeV459 &&
    type !== protectedV458LogsTypeV459
  ) {
    const reservedRequestsV459 =
      Math.max(
        0,
        safeNumber(
          completeExactPoolReserveV459
            ?.reservedRequests
        )
      );

    const notificationReserveRemainingV459 =
      budget.notification
        ?.globalReserveActiveV174 === true
        ? Math.max(
            0,
            safeNumber(
              budget.notification?.limit
            ) -
            safeNumber(
              budget.notification?.used
            )
          )
        : 0;

    const preTelegramGlobalLimitV459 =
      Math.max(
        0,
        safeNumber(budget.totalLimit) -
          notificationReserveRemainingV459
      );

    const analysisCapacityProtectedV459 =
      safeNumber(budget.analysis?.used) +
        amount <=
      Math.max(
        0,
        effectiveAnalysisLimitV416(budget) -
          reservedRequestsV459
      );

    const globalCapacityProtectedV459 =
      safeNumber(budget.totalUsed) +
        amount <=
      Math.max(
        0,
        preTelegramGlobalLimitV459 -
          reservedRequestsV459
      );

    if (
      !analysisCapacityProtectedV459 ||
      !globalCapacityProtectedV459
    ) {
      completeExactPoolReserveV459
        .lowerPriorityRequestsBlocked =
        safeNumber(
          completeExactPoolReserveV459
            .lowerPriorityRequestsBlocked
        ) + 1;

      budget.skipped.push({
        phase,
        type,
        amount,
        reason:
          "V459_COMPLETE_EXACT_POOL_REQUESTS_RESERVED",
        reservedFor:
          completeExactPoolReserveV459
            ?.targetAddress ||
          null
      });

      return false;
    }
  }

  if (
    phase ===
      "analysis" &&
    usdGReserveV182
      ?.active ===
      true &&
    type !==
      protectedUsdGTypeV182 &&
    type !==
      protectedUsdCompletionTypeV254 &&
    type !==
      protectedHolderCountCompletionTypeV256 &&
    type !==
      protectedV458TimestampTypeV459 &&
    type !==
      protectedV458LogsTypeV459 &&
    type !==
      "DEXSCREENER_ATH_FAIR_SLOT_V299"
  ) {
    const reservedRequestsV182 =
      Math.max(
        0,
        safeNumber(
          usdGReserveV182
            .reservedRequests
        )
      );

    const notificationReserveRemainingV182 =
      (
        budget.notification
          ?.globalReserveActiveV174 ===
          true
      )
        ? Math.max(
            0,
            safeNumber(
              budget.notification
                ?.limit
            ) -
            safeNumber(
              budget.notification
                ?.used
            )
          )
        : 0;

    const preTelegramGlobalLimitV182 =
      Math.max(
        0,
        budget.totalLimit -
          notificationReserveRemainingV182
      );

    const analysisCapacityProtectedV182 =
      budget.analysis.used +
        amount <=
      Math.max(
        0,
        effectiveAnalysisLimitV416(budget) -
          reservedRequestsV182
      );

    const globalCapacityProtectedV182 =
      budget.totalUsed +
        amount <=
      Math.max(
        0,
        preTelegramGlobalLimitV182 -
          reservedRequestsV182
      );

    if (
      !analysisCapacityProtectedV182 ||
      !globalCapacityProtectedV182
    ) {
      budget.skipped.push({
        phase,
        type,
        amount,
        reason:
          "V182_BLOCKSCOUT_USDG_REQUEST_RESERVED"
      });

      return false;
    }
  }

  if (
    phase === "analysis" &&
    athFairSlotReserveBlocksAnalysisV301(budget, type, amount)
  ) {
    budget.skipped.push({
      phase,
      type,
      amount,
      reason: "V301_ATH_FAIR_SLOT_REQUEST_RESERVED"
    });
    return false;
  }

  if (
    !budgetAvailable(
      budget,
      phase,
      amount
    )
  ) {
    budget.skipped.push({
      phase,
      type,
      amount,

      reason:
        "PHASE_BUDGET_EXHAUSTED"
    });

    return false;
  }

  budget.totalUsed +=
    amount;

  if (
    phase === "analysis" &&
    budget.analysis?.athFairSlotReserveV301?.active === true &&
    (type === "DEXSCREENER" || type === "DEXSCREENER_ATH_FAIR_SLOT_V299")
  ) {
    const reserve = budget.analysis.athFairSlotReserveV301;
    reserve.active = false;
    reserve.consumed = true;
    reserve.consumedAt = Date.now();
    reserve.consumedBy = type === "DEXSCREENER"
      ? "SCANNER_FRESH_DEXSCREENER"
      : "ATH_FAIR_SLOT";
    reserve.releasedAt = reserve.consumedAt;
    reserve.releaseReason = type === "DEXSCREENER"
      ? "CANDIDATE_FIRST_RIGHT_USED"
      : "ATH_FAIR_SLOT_USED";
  }

  /*
   * V279: exact request-type accounting for the isolated Telegram /analyse
   * budget only. This is observation-only telemetry and does not change any
   * request allowance, ordering, provider state or scanner accounting.
   */
  if (
    budget?.manualAnalyseTelemetryV279
      ?.enabled === true
  ) {
    const key =
      String(type || "UNKNOWN");

    budget.manualAnalyseTelemetryV279
      .consumed[key] =
      safeNumber(
        budget.manualAnalyseTelemetryV279
          .consumed[key]
      ) + amount;
  }

  if (
    phase ===
      "analysis" &&
    (
      type ===
        "BLOCKSCOUT_V4_USDG_DIRECTIONAL_V180" ||
      type ===
        "BLOCKSCOUT_V4_USD_COMPLETION_V254" ||
      type ===
        "BLOCKSCOUT_PRO_HOLDER_COUNT_COMPLETION_V256"
    ) &&
    budget.analysis
      ?.blockscoutUsdGReserveV182
      ?.active ===
      true
  ) {
    budget.analysis
      .blockscoutUsdGReserveV182
      .active =
        false;

    budget.analysis
      .blockscoutUsdGReserveV182
      .consumed =
        true;

    budget.analysis
      .blockscoutUsdGReserveV182
      .consumedAt =
        Date.now();
  }

  if (
    phase ===
    "system"
  ) {
    budget.system.used +=
      amount;
  }

  else if (
    phase ===
    "analysis"
  ) {
    budget.analysis.used +=
      amount;
  }

  else if (
    phase ===
    "notification"
  ) {
    budget.notification.used +=
      amount;
  }

  else if (
    phase ===
    "discovery-live"
  ) {
    budget.discovery.used +=
      amount;

    budget.discovery.liveUsed +=
      amount;
  }

  else if (
    phase ===
    "discovery-backlog"
  ) {
    budget.discovery.used +=
      amount;

    budget.discovery.backlogUsed +=
      amount;
  }

  return true;
}

function releaseNotificationReserveV174(
  budget
) {
  const wasActive =
    budget.notification
      ?.globalReserveActiveV174 ===
    true;

  const unusedAtRelease =
    Math.max(
      0,
      safeNumber(
        budget.notification
          ?.limit
      ) -
      safeNumber(
        budget.notification
          ?.used
      )
    );

  if (
    budget.notification
  ) {
    budget.notification
      .globalReserveActiveV174 =
        false;

    budget.notification
      .reserveReleasedAtV174 =
        Date.now();
  }

  return {
    enabled:
      true,
    wasActive,
    unusedRequestsReleased:
      unusedAtRelease,
    notificationUsed:
      safeNumber(
        budget.notification
          ?.used
      ),
    notificationLimit:
      safeNumber(
        budget.notification
          ?.limit
      ),
    hardRequestLimit:
      budget.totalLimit,
    releasedAfterTelegram:
      true
  };
}

function activatePostAnalysisBacklogReclaimV170(
  budget
) {
  const discoveryRemaining =
    Math.max(
      0,
      budget.discovery.limit -
        budget.discovery.used
    );

  const reclaimCapacity =
    Math.min(
      V170_POST_ANALYSIS_BACKLOG_RECLAIM_MAX_REQUESTS,
      discoveryRemaining
    );

  const originalBacklogLimit =
    safeNumber(
      budget.discovery
        .originalBacklogLimitV170
    ) ||
    BACKLOG_DISCOVERY_REQUEST_LIMIT;

  budget.discovery
    .postAnalysisBacklogReclaimV170 =
      reclaimCapacity > 0;

  budget.discovery.backlogLimit =
    Math.min(
      budget.discovery.limit,
      Math.max(
        budget.discovery.backlogLimit,
        budget.discovery.backlogUsed +
          reclaimCapacity
      )
    );

  return {
    enabled:
      true,
    activated:
      reclaimCapacity > 0,
    reclaimCapacityRequests:
      reclaimCapacity,
    originalBacklogLimit,
    effectiveBacklogLimit:
      budget.discovery.backlogLimit,
    discoveryRemainingBeforeReclaim:
      discoveryRemaining,
    analysisUsed:
      budget.analysis.used,
    analysisLimit:
      budget.analysis.limit,
    effectiveAnalysisLimitV416:
      effectiveAnalysisLimitV416(budget),
    adaptiveAnalysisBorrowedV416:
      safeNumber(budget.analysis?.adaptiveHeadroomV416?.borrowedRequests),
    notificationUsed:
      budget.notification.used,
    notificationLimit:
      budget.notification.limit,
    hardRequestLimit:
      budget.totalLimit,
    discoveryLimit:
      budget.discovery.limit,
    analysisLimitUnchanged:
      budget.analysis.limit ===
        ANALYSIS_REQUEST_LIMIT,
    hardRequestLimitUnchanged:
      budget.totalLimit ===
        MAX_EXTERNAL_REQUESTS
  };
}

function budgetTelemetry(
  budget
) {
  return {
    used:
      budget.totalUsed,

    limit:
      budget.totalLimit,

    rpcProviderHealthV423:
      rpcProviderHealthTelemetryV423(
        budget
      ),

    rpcHealthRoutingV424:
      rpcHealthRoutingTelemetryV424(
        budget
      ),

    marketProviderPressureV428:
      marketProviderPressureTelemetryV428(
        budget,
        null
      ),

    remaining:
      Math.max(
        0,
        budget.totalLimit -
          budget.totalUsed
      ),

    system: {
      used:
        budget.system.used,

      limit:
        budget.system.limit,

      remaining:
        Math.max(
          0,
          budget.system.limit -
            budget.system.used
        )
    },

    discovery: {
      used:
        budget.discovery.used,

      limit:
        budget.discovery.limit,

      remaining:
        Math.max(
          0,
          budget.discovery.limit -
            budget.discovery.used
        ),

      live: {
        used:
          budget.discovery.liveUsed,

        limit:
          budget.discovery.liveLimit,

        remaining:
          Math.max(
            0,
            budget.discovery.liveLimit -
              budget.discovery.liveUsed
          )
      },

      backlog: {
        used:
          budget.discovery.backlogUsed,

        limit:
          budget.discovery.backlogLimit,

        remaining:
          Math.max(
            0,
            budget.discovery.backlogLimit -
              budget.discovery.backlogUsed
          ),

        originalLimitV170:
          safeNumber(
            budget.discovery
              .originalBacklogLimitV170
          ) ||
          BACKLOG_DISCOVERY_REQUEST_LIMIT,

        postAnalysisReclaimActiveV170:
          budget.discovery
            .postAnalysisBacklogReclaimV170 ===
          true
      }
    },

    analysis: {
      used:
        budget.analysis.used,

      limit:
        effectiveAnalysisLimitV416(budget),

      baseLimitV416:
        safeNumber(budget.analysis?.baseLimitV416) || budget.analysis.limit,

      adaptiveBorrowedV416:
        safeNumber(budget.analysis?.adaptiveHeadroomV416?.borrowedRequests),

      adaptiveHeadroomV416:
        budget.analysis?.adaptiveHeadroomV416 || null,
      completeExactPoolReserveV459:
        budget.analysis?.completeExactPoolReserveV459 || null,

      remaining:
        Math.max(
          0,
          effectiveAnalysisLimitV416(budget) -
            budget.analysis.used
        ),

      protected:
        true,

      priorityHolderEvidenceCompletionV226:
        budget.analysis
          ?.priorityHolderEvidenceCompletionV226 ||
        {
          enabled: true,
          yields: 0,
          address: null,
          reason: null,
          yieldedAt: null,
          reserveWasBlocking: false
        },

      athFairSlotReserveV301:
        budget.analysis?.athFairSlotReserveV301 || null,

      blockscoutUsdGReserveV182: {
        active:
          budget.analysis
            ?.blockscoutUsdGReserveV182
            ?.active === true,
        consumed:
          budget.analysis
            ?.blockscoutUsdGReserveV182
            ?.consumed === true,
        releasedWithoutUse:
          budget.analysis
            ?.blockscoutUsdGReserveV182
            ?.releasedWithoutUse === true,
        yieldedToPriorityHolderEvidenceV226:
          budget.analysis
            ?.blockscoutUsdGReserveV182
            ?.yieldedToPriorityHolderEvidenceV226 === true,
        yieldedForAddressV226:
          budget.analysis
            ?.blockscoutUsdGReserveV182
            ?.yieldedForAddressV226 || null,
        releaseReasonV226:
          budget.analysis
            ?.blockscoutUsdGReserveV182
            ?.releaseReasonV226 || null
      }
    },

    notification: {
      used:
        budget.notification.used,

      limit:
        budget.notification.limit,

      remaining:
        Math.max(
          0,
          budget.notification.limit -
            budget.notification.used
        ),

      protected:
        true,

      globalReserveActiveV174:
        budget.notification
          .globalReserveActiveV174 ===
        true,

      globalReserveRemainingV174:
        budget.notification
          .globalReserveActiveV174 ===
        true
          ? Math.max(
              0,
              budget.notification.limit -
                budget.notification.used
            )
          : 0,

      reserveReleasedAtV174:
        budget.notification
          .reserveReleasedAtV174 ||
        null,

      exactNetworkRequestAccountingV174:
        true
    },

    hardPhaseIsolation:
      true,

    liveDownstreamReserve:
      LIVE_GLOBAL_RESERVE,

    liveFirstIsolation:
      true,

    telegramBudgeted:
      true,

    skipped:
      budget.skipped
  };
}

