/* =========================================================
   V268 SUCCESSFUL ALERT HISTORY
   ========================================================= */

function normalizeAlertHistoryV268(
  value
) {
  const entries =
    Array.isArray(
      value?.entries
    )
      ? value.entries
      : [];

  return {
    schemaVersion:
      "V268_ALERT_HISTORY_1",

    maximumEntries:
      ALERT_HISTORY_MAX_ENTRIES_V268,

    entries:
      entries
        .filter(
          item =>
            item &&
            typeof item ===
              "object" &&
            item?.snapshot &&
            typeof item
              .snapshot ===
              "object"
        )
        .slice(
          0,
          ALERT_HISTORY_MAX_ENTRIES_V268
        )
  };
}


function alertHistoryEntryV268(
  snapshot
) {
  const savedAt =
    safeNumber(
      snapshot?.savedAt
    ) ||
    Date.now();

  const address =
    normalize(
      snapshot
        ?.alert
        ?.address
    );

  return {
    id:
      [
        savedAt,
        address ||
          "unknown"
      ].join(
        ":"
      ),

    savedAt,

    address:
      address ||
      null,

    symbol:
      snapshot
        ?.alert
        ?.symbol ||
      null,

    name:
      snapshot
        ?.alert
        ?.name ||
      null,

    botVersion:
      snapshot?.botVersion ||
      VERSION,

    snapshot
  };
}


async function appendAlertHistoryV268(
  env,
  snapshot
) {
  const {
    kv,
    binding
  } = getKV(
    env
  );

  if (!kv) {
    return {
      saved: false,
      binding: null,
      key:
        ALERT_HISTORY_KEY_V268,
      maximumEntries:
        ALERT_HISTORY_MAX_ENTRIES_V268,
      entryCount: 0,
      error:
        "KV_NOT_CONFIGURED"
    };
  }

  try {
    let existingRaw =
      null;

    try {
      existingRaw =
        await kv.get(
          ALERT_HISTORY_KEY_V268
        );
    }

    catch (readError) {
      return {
        saved: false,
        binding,
        key:
          ALERT_HISTORY_KEY_V268,
        maximumEntries:
          ALERT_HISTORY_MAX_ENTRIES_V268,
        entryCount: null,
        error:
          "ALERT_HISTORY_READ_FAILED: " +
          errorString(
            readError
          )
      };
    }

    let existing = {
      schemaVersion:
        "V268_ALERT_HISTORY_1",
      maximumEntries:
        ALERT_HISTORY_MAX_ENTRIES_V268,
      entries: []
    };

    if (
      existingRaw
    ) {
      try {
        existing =
          normalizeAlertHistoryV268(
            JSON.parse(
              existingRaw
            )
          );
      }

      catch {
        /*
         * Corrupt diagnostic history must never block a successful alert.
         * Start a new V268 diagnostic history rather than guessing content.
         */
        existing = {
          schemaVersion:
            "V268_ALERT_HISTORY_1",
          maximumEntries:
            ALERT_HISTORY_MAX_ENTRIES_V268,
          entries: []
        };
      }
    }

    const entry =
      alertHistoryEntryV268(
        snapshot
      );

    const withoutDuplicate =
      existing.entries.filter(
        item =>
          item?.id !==
          entry.id
      );

    const entries = [
      entry,
      ...withoutDuplicate
    ].slice(
      0,
      ALERT_HISTORY_MAX_ENTRIES_V268
    );

    const history = {
      schemaVersion:
        "V268_ALERT_HISTORY_1",

      maximumEntries:
        ALERT_HISTORY_MAX_ENTRIES_V268,

      updatedAt:
        Date.now(),

      entries
    };

    await kv.put(
      ALERT_HISTORY_KEY_V268,
      jsonStringifySafeV246(
        history,
        0
      )
    );

    return {
      saved: true,
      binding,
      key:
        ALERT_HISTORY_KEY_V268,
      maximumEntries:
        ALERT_HISTORY_MAX_ENTRIES_V268,
      entryCount:
        entries.length,
      newestEntryId:
        entry.id,
      error: null
    };
  }

  catch (error) {
    return {
      saved: false,
      binding,
      key:
        ALERT_HISTORY_KEY_V268,
      maximumEntries:
        ALERT_HISTORY_MAX_ENTRIES_V268,
      entryCount: null,
      error:
        errorString(
          error
        )
    };
  }
}


