/* =========================================================
   HEALTH
   ========================================================= */

async function health(
  env
) {
  const budget =
    createBudget();

  const result =
    await readState(
      env
    );

  const state =
    result.state;

  const rpcHealthHydrationV426 =
    hydrateRpcHealthV426(
      state,
      budget
    );

  pruneState(
    state,
    true
  );

  let latest =
    null;

  let provider =
    null;

  let error =
    null;

  try {
    const response =
      await latestBlock(
        env,
        budget
      );

    latest =
      Number(
        response.block
      );

    provider =
      response.provider;
  }

  catch (err) {
    error =
      errorString(
        err
      );
  }

  const discovery =
    discoveryService(
      state
    );

  const dex =
    dexService(
      state
    );

  const lastScheduledRun =
    safeNumber(
      state.scheduler
        ?.lastScheduledRunAt
    );

  const scheduledAgeMinutes =
    lastScheduledRun
      ? (
          Date.now() -
          lastScheduledRun
        ) /
        60000
      : null;

  const backlogRemaining =
    latest !==
      null &&
    state.lastScannedBlock !==
      null &&
    state.lastScannedBlock !==
      undefined
      ? Math.max(
          0,

          latest -
          safeNumber(
            state.lastScannedBlock
          )
        )
      : null;

  return {
    agent:
      "Robinhood Chain Meme Hunter",

    version:
      VERSION,

    status:
      error
        ? "DEGRADED"
        : "ONLINE",

    routes: [
      "/health",
      "/rpc-test",
      "/scan",
      "/state",
      "/diagnostics",
      "/run-all",
      "/test-telegram",
      "/telegram-webhook",
      "/telegram-webhook-setup",
      "/telegram-webhook-status",
      "/telegram-webhook-info",
      "/last-alert-scan",
      "/alert-history",
      "/call-performance"
    ],

    chain: {
      name:
        CHAIN_NAME,

      chainId:
        CHAIN_ID
    },

    rpcStatus:
      error
        ? "ERROR"
        : "CONNECTED",

    latestBlock:
      latest,

    rpcProvider:
      provider,

    error,

    alchemyConfigured:
      Boolean(
        env.ALCHEMY_API_KEY
      ),

    persistence: {
      kvConfigured:
        result.persistent,

      binding:
        result.binding,

      stateKey:
        STATE_KEY,

      lastScannedBlock:
        state.lastScannedBlock,

      lastLiveScannedBlock:
        state.lastLiveScannedBlock,

      backlogRemaining,

      backlogLag:
        backlogRemaining ===
          null
          ? "UNKNOWN"
          : backlogLagLabel(
              backlogRemaining
            ),

      watchedTokens:
        state.watchedTokens.length,

      snapshotTokens:
        Object.keys(
          state.snapshots ||
          {}
        ).length,

      stateError:
        result.error
    },

    scheduler: {
      scheduledRunCount:
        safeNumber(
          state.scheduler
            ?.scheduledRunCount
        ),

      lastScheduledRunAt:
        state.scheduler
          ?.lastScheduledRunAt ||
        null,

      lastScheduledSuccessAt:
        state.scheduler
          ?.lastScheduledSuccessAt ||
        null,

      lastScheduledStatus:
        state.scheduler
          ?.lastScheduledStatus ||
        null,

      lastScheduledLatestBlock:
        state.scheduler
          ?.lastScheduledLatestBlock ||
        null,

      minutesSinceScheduledRun:
        scheduledAgeMinutes,

      fiveMinuteCronLikelyActive:
        scheduledAgeMinutes !==
          null &&
        scheduledAgeMinutes <=
          10
    },

    discoveryRpc: {
      publicLearnedBacklogChunkBlocks:
        discovery
          .publicBacklogChunkBlocks,

      alchemyLearnedBacklogChunkBlocks:
        discovery
          .alchemyBacklogChunkBlocks,

      publicFailedUpperBound:
        discovery
          .publicBacklogFailedUpperBound,

      alchemyFailedUpperBound:
        discovery
          .alchemyBacklogFailedUpperBound,

      learnedLiveChunkBlocks:
        discovery
          .liveChunkBlocks,

      publicCooldownActive:
        discoveryProviderCooling(
          state,
          "ROBINHOOD_PUBLIC_RPC"
        ),

      publicTotal429s:
        discovery
          .publicTotal429s,

      alchemyCooldownActive:
        discoveryProviderCooling(
          state,
          "ALCHEMY"
        ),

      alchemyTotal429s:
        discovery
          .alchemyTotal429s
    },

    services: {
      dexscreener: {
        lastStatus:
          dex.lastStatus,

        cooldownActive:
          safeNumber(
            dex.cooldownUntil
          ) >
          Date.now(),

        cooldownUntil:
          dex.cooldownUntil,

        total429s:
          dex.total429s
      }
    },

    telegram: {
      configured:
        Boolean(
          env.TELEGRAM_BOT_TOKEN &&
          env.TELEGRAM_CHAT_ID
        ),

      automaticCalls:
        true,

      richV77Style:
        true,

      minimumScore:
        MIN_ALERT_SCORE,

      minimumConfidence:
        MIN_CONFIDENCE_ALERT,

      minimumLiquidityUsd:
        MIN_ALERT_LIQUIDITY,

      verifiedRiskRequired:
        true
    },

    architecture:
      "V158_CORE_EVIDENCE_QUALITY_SCORE_PROTECTION_V77_TELEGRAM_HUNTER",

    timestamp:
      now()
  };
}

/* =========================================================
   RPC TEST
   ========================================================= */

async function rpcTest(
  env
) {
  const budget =
    createBudget();

  const startedAt =
    Date.now();

  try {
    const latest =
      await latestBlock(
        env,
        budget
      );

    const from =
      latest.block >
      2n
        ? latest.block -
          2n
        : 0n;

    const logs =
      await getLogsSingleProvider(
        env,
        from,
        latest.block,
        budget,
        "discovery-live",
        latest.provider ||
          "ROBINHOOD_PUBLIC_RPC"
      );

    return {
      agent:
        "Robinhood Chain Meme Hunter",

      version:
        VERSION,

      success:
        Array.isArray(
          logs.result
        ),

      latestBlock:
        Number(
          latest.block
        ),

      provider:
        logs.provider ||
        latest.provider,

      poolManager:
        POOL_MANAGER,

      poolManagerLogs:
        Array.isArray(
          logs.result
        )
          ? logs.result.length
          : 0,

      error:
        logs.error,

      requestBudget:
        budgetTelemetry(
          budget
        ),

      durationMs:
        Date.now() -
        startedAt,

      timestamp:
        now()
    };
  }

  catch (error) {
    return {
      agent:
        "Robinhood Chain Meme Hunter",

      version:
        VERSION,

      success:
        false,

      error:
        errorString(
          error
        ),

      requestBudget:
        budgetTelemetry(
          budget
        ),

      timestamp:
        now()
    };
  }
}

