/* =========================================================
   V273 TELEGRAM WEBHOOK DIAGNOSTICS
   ========================================================= */

function telegramUpdateTypeV273(
  update
) {
  if (update?.message) {
    return "message";
  }

  if (update?.edited_message) {
    return "edited_message";
  }

  if (update?.channel_post) {
    return "channel_post";
  }

  if (update?.edited_channel_post) {
    return "edited_channel_post";
  }

  return "UNKNOWN";
}

function telegramMessageFromUpdateV273(
  update
) {
  return (
    update?.message ||
    update?.edited_message ||
    update?.channel_post ||
    update?.edited_channel_post ||
    null
  );
}

async function persistTelegramWebhookDiagnosticV273(
  env,
  snapshot
) {
  try {
    const binding =
      env.MEME_HUNTER_STATE;

    if (
      !binding ||
      typeof binding.put !==
        "function"
    ) {
      return {
        persisted: false,
        reason:
          "MEME_HUNTER_STATE_KV_UNAVAILABLE"
      };
    }

    await binding.put(
      TELEGRAM_WEBHOOK_DIAGNOSTIC_KEY_V273,
      JSON.stringify(
        snapshot
      )
    );

    return {
      persisted: true,
      key:
        TELEGRAM_WEBHOOK_DIAGNOSTIC_KEY_V273
    };
  } catch (error) {
    return {
      persisted: false,
      reason:
        "KV_WRITE_FAILED",
      error:
        errorString(error)
    };
  }
}

async function telegramWebhookStatusV273(
  env
) {
  const binding =
    env.MEME_HUNTER_STATE;

  if (
    !binding ||
    typeof binding.get !==
      "function"
  ) {
    return {
      agent:
        "Robinhood Chain Meme Hunter",
      version:
        VERSION,
      status:
        "TELEGRAM_WEBHOOK_DIAGNOSTIC_KV_UNAVAILABLE",
      key:
        TELEGRAM_WEBHOOK_DIAGNOSTIC_KEY_V273,
      timestamp:
        now()
    };
  }

  const raw =
    await binding.get(
      TELEGRAM_WEBHOOK_DIAGNOSTIC_KEY_V273
    );

  if (!raw) {
    return {
      agent:
        "Robinhood Chain Meme Hunter",
      version:
        VERSION,
      status:
        "NO_TELEGRAM_WEBHOOK_UPDATE_SAVED",
      key:
        TELEGRAM_WEBHOOK_DIAGNOSTIC_KEY_V273,
      timestamp:
        now()
    };
  }

  try {
    return {
      agent:
        "Robinhood Chain Meme Hunter",
      version:
        VERSION,
      status:
        "TELEGRAM_WEBHOOK_UPDATE_AVAILABLE",
      key:
        TELEGRAM_WEBHOOK_DIAGNOSTIC_KEY_V273,
      snapshot:
        JSON.parse(raw),
      timestamp:
        now()
    };
  } catch (error) {
    return {
      agent:
        "Robinhood Chain Meme Hunter",
      version:
        VERSION,
      status:
        "TELEGRAM_WEBHOOK_DIAGNOSTIC_PARSE_FAILED",
      key:
        TELEGRAM_WEBHOOK_DIAGNOSTIC_KEY_V273,
      error:
        errorString(error),
      timestamp:
        now()
    };
  }
}



