function normalizeBlockscoutLogForV476V482(row) {
  if (
    !row ||
    typeof row !== "object"
  ) {
    return null;
  }

  const topics =
    Array.isArray(row?.topics)
      ? row.topics.map(value =>
          normalize(value)
        )
      : [
          row?.topic0,
          row?.topic1,
          row?.topic2,
          row?.topic3
        ]
          .filter(Boolean)
          .map(value =>
            normalize(value)
          );

  return {
    address:
      normalize(
        row?.address?.hash ||
        row?.address_hash ||
        row?.address ||
        ""
      ),
    topics,
    data:
      typeof row?.data === "string"
        ? row.data
        : "0x",
    transactionHash:
      normalize(
        row?.transactionHash ||
        row?.transaction_hash ||
        row?.hash ||
        ""
      ),
    blockNumber:
      row?.blockNumber ??
      row?.block_number ??
      null
  };
}

function parseBlockscoutProExactPonsV2LaunchV482(
  body,
  requestedAddress
) {
  const requested =
    normalize(requestedAddress);

  const status =
    body?.status !== undefined &&
    body?.status !== null
      ? String(body.status)
      : null;

  const message =
    body?.message !== undefined &&
    body?.message !== null
      ? String(body.message)
      : null;

  const rows =
    Array.isArray(body?.result)
      ? body.result
      : [];

  const decoded = [];

  for (const raw of rows) {
    const normalizedLog =
      normalizeBlockscoutLogForV476V482(
        raw
      );

    if (!normalizedLog) {
      continue;
    }

    const event =
      decodeDirectOnChainLaunchV476(
        normalizedLog
      );

    if (
      event?.decodeVerified === true &&
      event?.protocolKey === "pons_v2" &&
      normalize(event?.factory) ===
        normalize(PONS_V2_FACTORY_V215) &&
      normalize(event?.token) ===
        requested
    ) {
      decoded.push(event);
    }
  }

  const exact =
    decoded[0] || null;

  return {
    blockscoutStatus:
      status,
    blockscoutMessage:
      message,
    resultCount:
      rows.length,
    strictDecodedMatches:
      decoded.length,
    exact,
    strictlyVerified:
      Boolean(exact),
    source:
      "BLOCKSCOUT_PRO_EXACT_PONS_V2_TOKENLAUNCHED_DIAGNOSTIC_V482"
  };
}

