function parseBlockscoutProGetContractCreationV481(
  body,
  requestedAddress
) {
  const requested =
    normalize(requestedAddress);

  const status =
    body?.status !== undefined &&
    body?.status !== null
      ? String(body.status)
      : null;

  const message =
    body?.message !== undefined &&
    body?.message !== null
      ? String(body.message)
      : null;

  const rows =
    Array.isArray(body?.result)
      ? body.result
      : [];

  const matches =
    rows
      .map(row => {
        const contractAddress =
          normalize(
            row?.contractAddress ||
            row?.contract_address ||
            null
          );

        const contractCreator =
          normalize(
            row?.contractCreator ||
            row?.contract_creator ||
            null
          );

        const creationTransactionHash =
          normalize(
            row?.txHash ||
            row?.tx_hash ||
            row?.creationTransactionHash ||
            row?.creation_transaction_hash ||
            null
          );

        const requestedAddressMatch =
          isAddress(contractAddress) &&
          contractAddress === requested;

        const creatorValid =
          isAddress(contractCreator);

        const creationTransactionValid =
          /^0x[a-f0-9]{64}$/.test(
            creationTransactionHash || ""
          );

        return {
          contractAddress:
            contractAddress || null,
          contractCreator:
            creatorValid
              ? contractCreator
              : null,
          creationTransactionHash:
            creationTransactionValid
              ? creationTransactionHash
              : null,
          requestedAddressMatch,
          creatorValid,
          creationTransactionValid,
          strictlyVerified:
            requestedAddressMatch &&
            creatorValid &&
            creationTransactionValid
        };
      })
      .filter(row =>
        row.requestedAddressMatch
      );

  const exact =
    matches.find(row =>
      row.strictlyVerified
    ) ||
    matches[0] ||
    null;

  return {
    blockscoutStatus:
      status,
    blockscoutMessage:
      message,
    resultCount:
      rows.length,
    exactAddressMatches:
      matches.length,
    exactResult:
      exact,
    strictlyVerified:
      exact?.strictlyVerified === true,
    source:
      "BLOCKSCOUT_PRO_ETHERSCAN_COMPAT_GETCONTRACTCREATION_DIAGNOSTIC_V481"
  };
}

