function stripTelegramHtmlV500(
  message
) {
  return String(message || "")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/?(?:b|i|code|pre|u|s|strong|em)>/gi, "")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&");
}

async function sendLaunchSourcesTelegramV500(
  env,
  htmlMessage
) {
  const first =
    await sendTelegram(
      env,
      htmlMessage,
      null,
      null
    );

  if (
    first?.success === true
  ) {
    return {
      ...first,
      launchSourcesDeliveryV500:
        "HTML_PRIMARY_SUCCESS",
      fallbackAttempted:
        false
    };
  }

  if (
    !env.TELEGRAM_BOT_TOKEN ||
    !env.TELEGRAM_CHAT_ID
  ) {
    return {
      ...first,
      launchSourcesDeliveryV500:
        "HTML_FAILED_NO_TELEGRAM_CONFIG",
      fallbackAttempted:
        false
    };
  }

  const plain =
    stripTelegramHtmlV500(
      htmlMessage
    );

  const telegramBase =
    `https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}`;

  try {
    const response =
      await fetch(
        `${telegramBase}/sendMessage`,
        {
          method: "POST",
          headers: {
            "content-type":
              "application/json"
          },
          body: JSON.stringify({
            chat_id:
              env.TELEGRAM_CHAT_ID,
            text:
              plain,
            disable_web_page_preview:
              true
          })
        }
      );

    const data =
      await response.json();

    return {
      success:
        response.ok &&
        Boolean(data?.ok),
      status:
        response.status,
      mode:
        "TEXT_PLAIN_FALLBACK_V500",
      data,
      launchSourcesDeliveryV500:
        response.ok &&
        Boolean(data?.ok)
          ? "PLAIN_TEXT_FALLBACK_SUCCESS"
          : "PLAIN_TEXT_FALLBACK_FAILED",
      fallbackAttempted:
        true,
      primaryHtmlStatus:
        first?.status || null,
      primaryHtmlError:
        first?.error ||
        first?.data?.description ||
        null
    };
  } catch (error) {
    return {
      success: false,
      mode:
        "TEXT_PLAIN_FALLBACK_V500",
      error:
        errorString(error),
      launchSourcesDeliveryV500:
        "PLAIN_TEXT_FALLBACK_EXCEPTION",
      fallbackAttempted:
        true,
      primaryHtmlStatus:
        first?.status || null,
      primaryHtmlError:
        first?.error ||
        first?.data?.description ||
        null
    };
  }
}

