async function scheduledScan(
  env
) {
  const result =
    await scan(
      env,
      {
        scheduled:
          true
      }
    );

  /* V333 Step 1A: autonomous native V3 collection is isolated from the
   * scanner budget and fails open so it cannot stop the normal scheduled scan. */
  let nativeV3CollectorV333;
  try {
    nativeV3CollectorV333 = await scheduledNativeV3CollectorV333(env);
  } catch (error) {
    nativeV3CollectorV333 = {status:"SCHEDULED_NATIVE_V3_COLLECTOR_ERROR_V333",error:String(error?.message||error).slice(0,180)};
  }
  result.nativeV3CollectorV333 = nativeV3CollectorV333;

  console.log(
    jsonStringifySafeV246({
      event:
        "V97_SCHEDULED_SCAN",

      status:
        result.status,

      latestBlock:
        result.latestBlock,

      backlogAdvanced:
        result.persistence
          ?.backlogBlocksAdvanced,

      backlogRemaining:
        result.persistence
          ?.backlogRemaining,

      publicLearnedChunk:
        result.discoveryRpc
          ?.publicLearnedBacklogChunkBlocks,

      alchemyLearnedChunk:
        result.discoveryRpc
          ?.alchemyLearnedBacklogChunkBlocks,

      publicFailedUpperBound:
        result.discoveryRpc
          ?.publicFailedUpperBound,

      alchemyFailedUpperBound:
        result.discoveryRpc
          ?.alchemyFailedUpperBound,

      candidates:
        result.candidates
          ?.length,

      qualifying:
        result.qualifyingCandidates,

      excludedAssets:
        result.excludedAssets,

      deferredAnalysis:
        result.deferredAnalysis,

      requests:
        result.requestBudget
          ?.used,

      discoveryRequests:
        result.requestBudget
          ?.discovery
          ?.used,

      analysisRequests:
        result.requestBudget
          ?.analysis
          ?.used,

      notifications:
        result.requestBudget
          ?.notification
          ?.used,

      nativeV3CollectorV333:
        result.nativeV3CollectorV333,

      timestamp:
        now()
    })
  );

  return result;
}


